          max-width: 100%;
        }
      }
    </style>
    <script
      data-sigra-mermaid
      defer
      crossorigin="anonymous"
      integrity="sha384-T/0lMUdJpd2S1ZHtRiofG3htU3xPCrFVeAQ1UUE2TJwlEJSV5NUwn30kP28n238E"
      src="https://cdn.jsdelivr.net/npm/mermaid@11.16.0/dist/mermaid.min.js"
