test('adversarial record identity, shape, outcome and report controls fail closed', async (t) => {
  const mutations = {
    'null record': (r) => null,
    'empty record': () => ({}),
    'unknown seam': (r) => ({ ...r, seam: 'other' }),
    'case variant': (r) => ({ ...r, seam: 'NON_ADMIN_SMOKE' }),
