    'unexpected skip': (r) => { r.selected_steps[0].outcome = r.selected_steps[0].conclusion = 'skipped'; return r; },
    'cancelled body': (r) => { r.selected_steps[0].outcome = r.selected_steps[0].conclusion = 'cancelled'; return r; },
