        both = run("python3", ROOT / "scripts/ci/ci-hosted-gate-verify.py", "--mode", "pr", "--family", "docs-only", "--evidence",
                   self.write_attached("docs-attached.json", self.docs), cwd=ROOT, timeout=120)
