function loadR2Caps(withRetry) {
  const newAllowance = LOAD_R2_PREPARATION_MS + 4 * PROJECT_SLOT_MS + (withRetry ? PROJECT_SLOT_MS : 0) + LOAD_R2_HEADROOM_MS;
  const d19 = 2_042_596 + newAllowance;
