// The three R4 second windows (identical selection, projects, argv, ports, expected CLI exit and window sizes) under new
// identities. The retry keeps the R4 retry shape but is sized to the 135000 ms second window it can only ever re-run.
export function loadRecoverySlotDefinitionsR5() {
  const r4 = loadRecoverySlotDefinitionsR4();
  const regular = r4.slice(1, 4).map((slot, index) => ({ ...slot, id: LOAD_R5_IDS[index], maps_from: LOAD_R5_MAPS_FROM[index] }));
  const retry = {
    ...r4[4], id: LOAD_R5_RETRY_ID, maps_from: LOAD_R5_RETRY_ID, work_ms: LOAD_R3_SECOND_WORK_MS,
    command_ms: LOAD_R3_SECOND_WORK_MS + LOAD_R3_CLEANUP_MS, max_duration_ms: LOAD_R3_SETUP_MS + LOAD_R3_SECOND_WORK_MS + LOAD_R3_CLEANUP_MS
  };
  return [...regular, retry];
}

function loadR5Caps(withRetry) {
  const slots = loadRecoverySlotDefinitionsR5();
  const regular = slots.slice(0, 3).reduce((sum, slot) => sum + slot.max_duration_ms, 0);
  const newAllowance = LOAD_R3_PREPARATION_MS + regular + (withRetry ? slots[3].max_duration_ms : 0) + LOAD_R3_HEADROOM_MS;
  const d19 = LOAD_R5_CARRIED_MS + newAllowance;
  const d19Launches = LOAD_R5_CARRIED_LAUNCHES + 3 + (withRetry ? 1 : 0);
  return { new_allowance_ms: newAllowance, d19_cap_ms: d19, d19_launch_max: d19Launches, shared_cap_ms: d19 + 9 * 240_000 + 3 * 60_000, physical_cli_max: d19Launches + 9 };
}

export function buildLoadRecoveryLedgerR5(input) {
  const errors = [];
  if (!Array.isArray(input?.charges) || JSON.stringify(input.charges) !== JSON.stringify(LOAD_R5_CHARGES)) errors.push('carried historical charges do not match the exact seventeen carried components');
  if (input?.physicalPlaywrightLaunches !== LOAD_R5_CARRIED_LAUNCHES) errors.push('carried Playwright CLI launch count must be exactly nine');
  if (JSON.stringify(input?.spentReservations) !== JSON.stringify(LOAD_R5_SPENT)) errors.push('spent reservation inventory must be the eleven closed identities');
  if (input?.retryUsed !== 1 || input?.retryAvailable !== 0) errors.push('original retry must remain used 1, available 0');
  if (input?.preparationUsedMs !== LOAD_R5_PREPARATION_USED_MS) errors.push('carried preparation used must be exactly 5141 + 822 + 821 = 6784 ms');
  if (errors.length) throw new Error(errors.join('; '));
  const priorCharge = input.charges.reduce((sum, value) => sum + value, 0);
  const slots = loadRecoverySlotDefinitionsR5();
  const caps = { approve: loadR5Caps(true), 'approve-without-retry': loadR5Caps(false) };
  if (priorCharge !== LOAD_R5_CARRIED_MS || JSON.stringify(caps) !== JSON.stringify(LOAD_R5_CAP_TABLE)
    || slots.slice(0, 3).some((slot) => slot.rows !== 2) || slots.slice(0, 3).reduce((sum, slot) => sum + slot.rows, 0) + LOAD_R5_CARRIED_ROWS !== 22) {
    throw new Error('R5 load recovery arithmetic, caps or row packing differs from the reviewed finite allocation');
  }
  return {
    prior_charge_ms: priorCharge, prior_playwright_cli_launches: LOAD_R5_CARRIED_LAUNCHES, spent_reservations: [...LOAD_R5_SPENT],
    expired_identities: [...LOAD_R5_EXPIRED], retired_identities: [...LOAD_R5_RETIRED],
    retry_used: 1, retry_available: 0, preparation_used_ms: LOAD_R5_PREPARATION_USED_MS, preparation_reserve_ms: LOAD_R3_PREPARATION_MS, slots,
    launch_unit: 'playwright_cli_process', engine_worker_lifecycle_accounting: 'separate_from_playwright_cli_launches',
    setup_ms: LOAD_R3_SETUP_MS, setup_charged_separately: true, cleanup_reserve_per_command_ms: LOAD_R3_CLEANUP_MS, headroom_ms: LOAD_R3_HEADROOM_MS,
    conditional_acceptance_slots: 9, conditional_acceptance_ms: 2_160_000, optional_seed_checks_ms: 180_000,
    caps, required_new_rows: 6, carried_rows: LOAD_R5_CARRIED_ROWS, required_rows: 22
  };
}

function sortKeysR5(value) {
  if (Array.isArray(value)) return value.map(sortKeysR5);
  if (value && typeof value === 'object') return Object.fromEntries(Object.keys(value).sort().map((key) => [key, sortKeysR5(value[key])]));
  return value;
}

export function canonicalJsonR5(value) { return JSON.stringify(sortKeysR5(value)); }

export function readLoadHistoryR5(root, deps = {}) {
  const d = { olderHistory: readLoadHistoryR4, lineage: LOAD_R5_LINEAGE, skipPreservedRevisions: false, ...deps };
  const older = d.olderHistory(root);
  for (const [name, record] of Object.entries(d.lineage)) {
    if (fileHash(path.join(root, record.file)) !== record.sha256) throw new Error(`R4 ${name} bytes changed: ${record.file}`);
  }
  const evidenceFile = path.join(root, d.lineage.evidence.file);
  const evidence = readJson(evidenceFile);
  const first = evidence.attempts?.[0];
  const halted = evidence.attempts?.[1];
  const limits = evidence.limits ?? {};
  const absence = halted?.prior_collision_absence;
  if (evidence.status !== 'halted' || evidence.attempts?.length !== 2
    || first?.slot_id !== LOAD_R5_FIRST_ID || first.observed_outcome !== 'native_rows_accepted' || first.charged_duration_ms !== 92_810 || first.playwright_cli?.launched !== true
    || halted?.slot_id !== LOAD_R5_HALTED_ID || halted.observed_outcome !== 'halted' || halted.charged_duration_ms !== 43_535 || halted.playwright_cli?.launched !== false
    || absence?.schema_version !== 'sigra.phase253.owned-account-count/v1' || absence.exit_code !== 3 || absence.query !== ACCOUNT_COUNT_QUERY
    || typeof evidence.stop_reason !== 'string' || !evidence.stop_reason
    || (evidence.infrastructure_halts ?? []).length !== 0 || evidence.infrastructure_retry?.eligible
    || evidence.preparation?.duration_ms !== 821 || limits.preparation_charge_ms !== 821
    || limits.charged_duration_ms !== LOAD_R5_CARRIED_MS || limits.prior_charge_ms !== LOAD_R4_CARRIED_MS
    || limits.physical_playwright_cli_launches !== LOAD_R5_CARRIED_LAUNCHES || JSON.stringify(limits.used_slots) !== JSON.stringify(LOAD_R5_SPENT)
    || limits.retry_used !== 1 || limits.retry_available !== 0 || limits.infra_retry?.used !== 0) {
    throw new Error('halted R4 receipt differs from the 2359703 ms, nine-launch, eleven-spent, non-infrastructure ledger');
  }
  const rawBase = `${evidenceFile}.raw`;
  const rawFiles = new Set();
  for (const item of [...collectReferencesR4(evidence.attempts), ...collectReferencesR4(evidence.preparation)]) {
    const file = confinedFile(rawBase, item);
    if (!file || fileHash(file) !== item.sha256) throw new Error(`halted R4 raw receipt readback differs: ${item.path}`);
    rawFiles.add(`${d.lineage.evidence.file}.raw/${item.path}`);
  }
  for (const found of listFilesR4(rawBase)) rawFiles.add(`${d.lineage.evidence.file}.raw/${found}`);
  if (!d.skipPreservedRevisions) {
    for (const revision of evidence.preserved_revisions ?? []) {
      if (sha256(readGitBlob(root, revision.ref)) !== revision.sha256) throw new Error(`halted R4 preserved revision readback differs: ${revision.ref}`);
    }
  }
  const charges = [...older.charges, evidence.preparation.duration_ms, first.charged_duration_ms, halted.charged_duration_ms];
  const ledger = buildLoadRecoveryLedgerR5({
    charges, physicalPlaywrightLaunches: limits.physical_playwright_cli_launches, spentReservations: limits.used_slots,
    retryUsed: limits.retry_used, retryAvailable: limits.retry_available, preparationUsedMs: 5141 + 822 + evidence.preparation.duration_ms
  });
  const terminalHalt = {
    slot_id: halted.slot_id, plan: '253-73', cause: LOAD_R5_HALT_CAUSE, terminal: true, infrastructure: false, retryable: false, charged: true,
    charged_ms: halted.charged_duration_ms, preparation_ms: evidence.preparation.duration_ms, stop_reason: evidence.stop_reason,
    summary: { file: d.lineage.summary.file, sha256: d.lineage.summary.sha256 },
    expired_identities: [LOAD_R4_RETRY_ID], retired_identities: LOAD_R4_IDS.slice(2)
  };
  const lineageFiles = [...Object.values(d.lineage).map((record) => record.file), ...rawFiles];
  const own = lineageFiles.map((file) => ({ path: file, sha256: fileHash(path.join(root, file)) }));
  if (own.some((item) => !item.sha256)) throw new Error('an R5 lineage record is missing an exact byte identity');
  const artifacts = [...older.artifacts.filter((item) => !lineageFiles.includes(item.path)), ...own];
  return { control: older.control, ledger, charges, terminalHalt, artifacts, lineage: d.lineage, frozenBlobs: { ...older.frozenBlobs } };
}

// Binds the accepted R4 first window by its committed bytes. The verdict must reproduce from those bytes through the unchanged
// R4 verifier, the halted evidence must carry the identical first attempt, and every raw file the attempt references is re-hashed.
export function carriedFirstWindowR5(root, deps = {}) {
  const d = {
    evidenceFile: path.join(root, LOAD_R5_LINEAGE.evidence.file), freezeFile: path.join(root, LOAD_R5_LINEAGE.freeze.file), rawBase: null,
    revisionCommit: LOAD_R5_CARRY_COMMIT, revisionSha256: LOAD_R5_CARRY_SHA256, readRevisionBytes: readFrozenBytesR2,
    verifyRevision: verifyLoadRecoveryEvidenceDataR4, verifyBinding: verifyFrozenSourceBindingR4, ...deps
  };
  const rawBase = d.rawBase ?? `${d.evidenceFile}.raw`;
  const bytes = d.readRevisionBytes(root, d.revisionCommit, LOAD_R4_EVIDENCE_PATH);
  if (sha256(bytes) !== d.revisionSha256) throw new Error('the committed first_complete R4 revision differs from its pinned sha256');
  const revision = JSON.parse(Buffer.from(bytes).toString('utf8'));
  if (revision.status !== 'first_complete') throw new Error(`the carried first-window revision status is ${revision.status}, expected first_complete`);
  const attempt = revision.attempts?.[0];
  if (revision.attempts?.length !== 1 || attempt?.slot_id !== LOAD_R5_FIRST_ID || attempt.lifecycle?.rows !== LOAD_R5_CARRIED_ROWS) throw new Error('the carried first-window revision does not hold exactly the 16-row first attempt');
  const freezeHash = fileHash(d.freezeFile);
  if (freezeHash !== LOAD_R5_LINEAGE.freeze.sha256) throw new Error('the R4 freeze bytes differ from the carried first-window binding');
  const freeze = readJson(d.freezeFile);
  if (freeze.source?.checkout_head !== LOAD_R5_CARRY_R4_HEAD) throw new Error('the R4 freeze commit differs from the carried first-window binding');
  const rawFiles = [];
  for (const item of collectReferencesR4(attempt)) {
    const file = confinedFile(rawBase, item);
    if (!file || fileHash(file) !== item.sha256) throw new Error(`carried first-window raw file differs from its recorded sha256: ${item.path}`);
    rawFiles.push({ path: `${LOAD_R4_EVIDENCE_PATH}.raw/${item.path}`, sha256: item.sha256 });
  }
  const verdict = d.verifyRevision(structuredClone(revision), freeze, rawBase, 'first', freezeHash);
  if (!verdict.ok) throw new Error(`the carried first-window revision no longer verifies: ${verdict.errors.join('; ')}`);
  d.verifyBinding(root, freeze, { terminal: true });
  const halted = readJson(d.evidenceFile);
  if (canonicalJsonR5(halted.attempts?.[0]) !== canonicalJsonR5(attempt)) throw new Error('the halted R4 evidence attempt 0 differs from the carried first-window revision attempt');
  const reportFile = confinedFile(rawBase, attempt.files?.playwright_report);
  if (!reportFile) throw new Error('the carried first-window attempt has no readable Playwright report');
  const contextIds = playReportTests(readJson(reportFile)).flatMap((row) => controlContextIdentitiesR4(row));
  if (new Set(contextIds).size !== contextIds.length) throw new Error('two carried rows reused the same browser-context identity');
  return {
    revision_commit: d.revisionCommit, revision_sha256: d.revisionSha256, evidence_path: LOAD_R4_EVIDENCE_PATH, evidence_sha256: fileHash(d.evidenceFile),
    attempt_sha256: sha256(canonicalJsonR5(attempt)), r4_freeze_sha256: freezeHash, r4_checkout_head: freeze.source.checkout_head,
    rows: attempt.lifecycle.rows, collision_receipts: structuredClone(attempt.collision_receipts), database: attempt.database.name,
    context_ids: contextIds, raw_files: rawFiles
  };
}

// ---- Phase 253 plan 79 task 3: R5 freeze, evidence initialisation and approval reader (modeled on R4; R4 stays untouched) ----
// The R5 source list is the R4 list plus the real-Postgres integration test and the auth-tables migration that fixes the count schema.
export const LOAD_R5_EXTRA_SOURCES = [...LOAD_R4_EXTRA_SOURCES, 'scripts/ci/ci-registration-recovery.pg.test.mjs', ACCOUNT_SCHEMA_SOURCES_R5.migration];
// The only pinned blobs allowed to differ from (or be absent in) the R4 freeze: the runner revision and its two tests.
const LOAD_R5_TOOLING = ['scripts/ci/ci-registration-recovery.mjs', 'scripts/ci/ci-registration-recovery.test.mjs', 'scripts/ci/ci-registration-recovery.pg.test.mjs'];
const LOAD_R5_CLOSED_NOTE = 'no reuse of any of the eleven spent identities';

export function loadR5SourceFileList(root) {
  return [...new Set([...loadR4SourceFileList(root), ...LOAD_R5_EXTRA_SOURCES])];
}

export function verifyFrozenSourceBindingR5(root, freeze, { terminal = false } = {}) {
  const head = git(['-C', root, 'rev-parse', 'HEAD']);
  const frozen = freeze?.source?.checkout_head;
  if (!frozen || run('git', ['-C', root, 'merge-base', '--is-ancestor', frozen, head]).status !== 0) throw new Error('frozen R5 source commit is not an ancestor of this checkout');
  for (const [file, expected] of Object.entries(freeze.source.blobs ?? {})) {
    if (terminal) {
      // Accepted evidence stays verifiable after later committed runner changes: bind by git objects, not the working tree.
      const blob = run('git', ['-C', root, 'rev-parse', `${frozen}:${file}`]);
      if (blob.status !== 0 || blob.stdout.trim() !== expected || run('git', ['-C', root, 'cat-file', '-t', expected]).stdout.trim() !== 'blob') throw new Error(`frozen R5 source blob mismatch at the frozen commit for ${file}`);
    } else if (git(['-C', root, 'hash-object', file]) !== expected) throw new Error(`frozen R5 source identity mismatch for ${file}`);
  }
  return head;
}

function verifyFrozenHistoryBindingR5(root, freeze, { terminal = false } = {}) {
  const frozen = freeze.source.checkout_head;
  for (const artifact of freeze.historical?.artifacts ?? []) {
    const actual = terminal ? sha256(readFrozenBytesR2(root, frozen, artifact.path)) : fileHash(path.join(root, artifact.path));
    if (actual !== artifact.sha256) throw new Error(`preserved R5 history changed: ${artifact.path}`);
  }
  const budget = terminal ? sha256(readFrozenBytesR2(root, frozen, LOAD_R5_BUDGET_PATH)) : fileHash(path.join(root, LOAD_R5_BUDGET_PATH));
  if (freeze.budget?.file !== LOAD_R5_BUDGET_PATH || !budget || freeze.budget.sha256 !== budget) throw new Error('the R5 budget document differs from the frozen binding');
}

function canonicalLedgerR5(freeze) {
  return buildLoadRecoveryLedgerR5({
    charges: freeze.historical?.carried_components_ms, physicalPlaywrightLaunches: freeze.historical?.physical_playwright_cli_launches,
    spentReservations: freeze.historical?.spent_reservations, retryUsed: freeze.historical?.spent_retry?.used,
    retryAvailable: freeze.historical?.spent_retry?.available, preparationUsedMs: LOAD_R5_PREPARATION_USED_MS
  });
}

// Seams are injectable so the freeze flow runs offline in a temporary committed checkout.
function loadR5FreezeDeps(deps = {}) {
  return {
    enforceNode: true, assertCheckout: assertRevisionCheckout, assertConfig: assertDirtyConfigPreserved, readHistory: readLoadHistoryR5, carriedFirst: carriedFirstWindowR5,
    sourceFiles: loadR5SourceFileList, requiredSources: () => [...SOURCE_FILES, ...LOAD_EXTRA_SOURCES, ...LOAD_R4_EXTRA_SOURCES, ...LOAD_R5_EXTRA_SOURCES],
    importClosure: discoverLoadImportClosure, runtimeIdentity: loadRuntimeIdentity, accountSchema: accountSchemaSourcesR5,
    r4Source: (root) => { const frozen = readJson(path.join(root, LOAD_R5_LINEAGE.freeze.file)); return { checkout_head: frozen.source.checkout_head, blobs: frozen.source.blobs }; },
    r4Blob: (root, head, file) => git(['-C', root, 'rev-parse', `${head}:${file}`]), ...deps
  };
}

// Every non-tooling blob must equal the R4 frozen blob; a newly pinned product file must equal its blob at the R4 checkout.
function sourceDeltaR5(root, blobs, d) {
  const r4 = d.r4Source(root);
  const changed = []; const addedTooling = []; const addedProduct = [];
  for (const [file, blob] of Object.entries(blobs)) {
    const tooling = LOAD_R5_TOOLING.includes(file);
    if (Object.hasOwn(r4.blobs, file)) {
      if (blob === r4.blobs[file]) continue;
      if (!tooling) throw new Error(`pinned blob differs from the R4 frozen blob: ${file}`);
      changed.push(file);
    } else if (tooling) addedTooling.push(file);
    else if (blob !== d.r4Blob(root, r4.checkout_head, file)) throw new Error(`newly pinned file differs from its blob at the R4 checkout: ${file}`);
    else addedProduct.push(file);
  }
  return { changed, added: [...addedTooling, ...addedProduct], r4_checkout_head: r4.checkout_head };
}

export function createLoadRecoveryFreezeR5(outputFile, root = ROOT, deps = {}) {
  const d = loadR5FreezeDeps(deps);
  if (fs.existsSync(outputFile)) throw new Error('refusing to overwrite the additive R5 load recovery freeze');
  if (d.enforceNode && process.version !== LOAD_NODE) throw new Error(`load recovery must be frozen under Node ${LOAD_NODE}`);
  d.assertCheckout(root);
  const head = git(['-C', root, 'rev-parse', 'HEAD']);
  const history = d.readHistory(root);
  const carried = d.carriedFirst(root);
  for (const artifact of history.artifacts) {
    if (sha256(readFrozenBytesR2(root, head, artifact.path)) !== artifact.sha256) throw new Error(`R5 lineage record is not committed at HEAD: ${artifact.path}`);
  }
  const budgetHash = fileHash(path.join(root, LOAD_R5_BUDGET_PATH));
  if (!budgetHash || sha256(readFrozenBytesR2(root, head, LOAD_R5_BUDGET_PATH)) !== budgetHash) throw new Error('the R5 budget document is missing or not committed at HEAD');
  const files = d.sourceFiles(root);
  const blobs = Object.fromEntries(files.map((file) => [file, git(['-C', root, 'rev-parse', `${head}:${file}`])]));
  const delta = sourceDeltaR5(root, blobs, d);
  const schema = d.accountSchema(root);
  const query = accountCountQueryR5(schema.name);
  const freeze = {
    schema_version: LOAD_R5_FREEZE_SCHEMA, status: 'frozen_before_results', plan: '253-82', revision: 'r5', frozen_at: new Date().toISOString(),
    context_identity: LOAD_R4_CONTEXT_MODE,
    source: { repository: 'szTheory/sigra', checkout_head: head, blobs },
    runtime: d.runtimeIdentity(root),
    historical: {
      artifacts: history.artifacts, frozen_blob_sets: history.frozenBlobs, carried_charge_ms: history.ledger.prior_charge_ms,
      carried_components_ms: history.charges, physical_playwright_cli_launches: LOAD_R5_CARRIED_LAUNCHES, spent_reservations: [...LOAD_R5_SPENT],
      expired_identities: [...LOAD_R5_EXPIRED], retired_identities: [...LOAD_R5_RETIRED],
      spent_retry: { used: 1, available: 0 }, terminal_halt: history.terminalHalt, halted_lineage: structuredClone(history.lineage ?? LOAD_R5_LINEAGE)
    },
    budget: { file: LOAD_R5_BUDGET_PATH, sha256: budgetHash, grants_capacity: false },
    ledger: history.ledger,
    carried_first_window: carried,
    // account_count.schema is the schema NAME (a string); the per-attempt count receipts keep their own object under schema_binding.
    account_count: { schema: schema.name, schema_sources: schema.sources, query, query_sha256: sha256(query) },
    source_delta_from_r4: delta,
    setup_accounting: {
      setup_ms: LOAD_R3_SETUP_MS, separately_bounded: true, separately_charged: true, command_deadline_starts_after_setup: true,
      setup_charge: 'max(monotonic, wall)', command_charge: 'max(monotonic, wall)', slot_charge: 'setup_charge + command_charge'
    },
    diagnostics: { per_test_jsonl_required_when_cli_launched: true, env: 'SIGRA_PLAYWRIGHT_FAILURE_JSONL', error_context_preserved: true, psql_stderr_sidecar: true },
    selection: {
      spec: 'tests/admin-eval.spec.ts', config: path.basename(LOAD_RECOVERY_CONFIG), original_title: CONTROL_BOARD_TITLE,
      first_titles: FIRST_CONTROLS, second_titles: CONTROL_SECOND_ACTIVE, deliberate_expected_failure_markers: CONTROL_EXPECTED_FAILURE_MARKERS,
      cli_grep_forbidden: true, workers: 1, fully_parallel: false, retries: 0, trace: 'retain-on-failure'
    },
    tools: {
      node: process.version, expected_node: LOAD_NODE, playwright: '1.59.1', parse5: '8.0.1',
      mix: history.control?.accepted?.toolchain?.mix, ecto_sql: history.control?.accepted?.toolchain?.ecto_sql, phoenix_live_view: history.control?.accepted?.toolchain?.phoenix_live_view
    },
    exclusions: ['no browser installation', 'no hidden --list or version CLI', 'no warmup', 'no duplicate full suite', LOAD_R5_CLOSED_NOTE, 'no reuse of the expired CR2/CR3/CR4 infrastructure retries or the retired CR-*-SECOND, CR3-*-SECOND and CR4-MOBILE/DARK-SECOND identities', 'no re-run of the carried accepted first window', 'no native or hosted work without a committed Jon approval record bound to the R5 budget document and this freeze', 'no capacity granted by this freeze'],
    stop_conditions: ['source or history digest mismatch', 'unexpected assertion or missing native report', 'database drop/build cleanup/report/trace sanitation failure', 'setup exceeds 60000 ms', 'command exceeds its frozen command_ms', 'host suspension detected', 'stalled owned process group remains alive', 'AC power, caffeinate holder or pmset assertion proof missing before predebit', 'a launched attempt lacks its per-test JSONL receipt', 'two different rows share a browser-context identity', 'account count query exits non-zero', 'carried first window binding fails re-verification']
  };
  freeze.freeze_sha256 = loadFreezeDigest(freeze);
  writeJson(outputFile, freeze);
  return freeze;
}

export function validateLoadRecoveryFreezeR5(root, freeze, { terminal = false, deps = {} } = {}) {
  const d = loadR5FreezeDeps(deps);
  d.assertConfig(root);
  if (freeze?.schema_version !== LOAD_R5_FREEZE_SCHEMA || freeze.status !== 'frozen_before_results' || freeze.context_identity !== LOAD_R4_CONTEXT_MODE
    || freeze.freeze_sha256 !== loadFreezeDigest(freeze)) throw new Error('R5 native load recovery freeze is malformed or its digest is invalid');
  const head = verifyFrozenSourceBindingR5(root, freeze, { terminal });
  for (const required of d.requiredSources()) if (!freeze.source.blobs?.[required]) throw new Error(`freeze omits required source ${required}`);
  if (!terminal) for (const file of d.importClosure(root)) if (!freeze.source.blobs?.[file]) throw new Error(`freeze omits actual imported runtime source ${file}`);
  verifyFrozenHistoryBindingR5(root, freeze, { terminal });
  if (JSON.stringify(freeze.ledger) !== JSON.stringify(canonicalLedgerR5(freeze))) throw new Error('frozen R5 ledger differs from the reviewed carried allocation');
  for (const slot of freeze.ledger.slots.slice(0, 3)) if (slot.argv.some((arg) => /^(-g|--grep)(=|$)/.test(arg))) throw new Error('frozen argv carries a CLI grep that would override per-project selection');
  const closed = [...freeze.historical.spent_reservations, ...freeze.historical.expired_identities, ...freeze.historical.retired_identities];
  if (freeze.ledger.slots.some((slot) => closed.includes(slot.id))) throw new Error('a frozen slot reuses a spent, expired or retired identity');
  const account = freeze.account_count;
  if (typeof account?.schema !== 'string' || account.query !== accountCountQueryR5(account.schema) || account.query_sha256 !== sha256(String(account.query))) {
    throw new Error('frozen account count query or schema differs from the reviewed schema-qualified query');
  }
  for (const source of account.schema_sources ?? []) {
    if (freeze.source.blobs?.[source.path] !== source.blob) throw new Error(`frozen account count schema source is not pinned at its blob: ${source.path}`);
  }
  if ((account.schema_sources ?? []).length !== 2) throw new Error('frozen account count must record exactly the migration and user schema sources');
  const carried = freeze.carried_first_window;
  if (carried?.revision_commit !== LOAD_R5_CARRY_COMMIT || carried.revision_sha256 !== LOAD_R5_CARRY_SHA256 || carried.rows !== LOAD_R5_CARRIED_ROWS
    || carried.r4_checkout_head !== LOAD_R5_CARRY_R4_HEAD || carried.evidence_path !== LOAD_R4_EVIDENCE_PATH) {
    throw new Error('carried first window binding differs from the reviewed first_complete R4 revision');
  }
  if (JSON.stringify(sourceDeltaR5(root, freeze.source.blobs, d)) !== JSON.stringify(freeze.source_delta_from_r4)) throw new Error('frozen source delta from R4 differs from the pinned blobs');
  if (!terminal) {
    if (JSON.stringify(freeze.runtime) !== JSON.stringify(d.runtimeIdentity(root))) throw new Error('locked/installed runtime or pinned transform identity changed');
    const schema = d.accountSchema(root);
    if (schema.name !== account.schema || JSON.stringify(schema.sources) !== JSON.stringify(account.schema_sources)) throw new Error('frozen account count schema differs from the schema derived from the pinned sources');
    const history = d.readHistory(root);
    if (JSON.stringify(history.ledger) !== JSON.stringify(freeze.ledger)) throw new Error('re-read R4 lineage differs from the frozen R5 ledger');
    if (JSON.stringify(history.terminalHalt) !== JSON.stringify(freeze.historical.terminal_halt)) throw new Error('re-read 253-73 terminal halt record differs from the frozen record');
    if (canonicalJsonR5(d.carriedFirst(root)) !== canonicalJsonR5(carried)) throw new Error('carried first window binding fails re-verification against the committed R4 bytes');
  }
  return head;
}

function checkLoadRecoveryFreezeFileR5(freezeFile, root = ROOT) {
  try {
    if (path.resolve(freezeFile) !== path.resolve(root, LOAD_R5_FREEZE_PATH)) throw new Error('freeze check accepts only the additive R5 path');
    validateLoadRecoveryFreezeR5(root, readJson(freezeFile));
    console.log('R5 native load recovery freeze verified: R4 lineage re-hashed, 2359703 ms/9 launches/11 spent carried, accepted first window bound, schema-qualified account count, setup bounded outside the work deadline, 6 new rows, no capacity granted');
    return { ok: true, errors: [] };
  } catch (error) {
    console.error(`R5 native load recovery freeze rejected: ${error.message}`);
    return { ok: false, errors: [error.message] };
  }
}

// Capacity is usable only through a record committed in HEAD and bound to the R5 budget document and freeze.
export function readCommittedApprovalR5(root, freezeFile, freeze) {
  const file = path.join(root, LOAD_R5_APPROVAL_PATH);
  if (!fs.existsSync(file)) throw new Error('R5 budget approval record is absent: capacity exists only after Jon\'s decision is recorded');
  const tracked = run('git', ['-C', root, 'ls-files', '--error-unmatch', '--', LOAD_R5_APPROVAL_PATH]);
  const inHead = run('git', ['-C', root, 'cat-file', '-e', `HEAD:${LOAD_R5_APPROVAL_PATH}`]);
  if (tracked.status !== 0 || inHead.status !== 0) throw new Error('R5 budget approval record is not committed in HEAD');
  const bytes = fs.readFileSync(file);
  if (!bytes.equals(readGitBlob(root, `HEAD:${LOAD_R5_APPROVAL_PATH}`))) throw new Error('R5 budget approval record differs from its committed bytes');
  const record = JSON.parse(bytes.toString('utf8'));
  if (record.schema_version !== LOAD_R5_APPROVAL_SCHEMA || !Object.hasOwn(LOAD_R5_CAP_TABLE, record.decision ?? '')) throw new Error('R5 budget approval record is malformed or carries an unrecognised decision');
  const budgetHash = fileHash(path.join(root, LOAD_R5_BUDGET_PATH));
  if (!budgetHash || record.budget_sha256 !== budgetHash || freeze?.budget?.sha256 !== budgetHash) throw new Error('R5 budget approval is not bound to the frozen budget document hash');
  if (record.freeze_sha256 !== fileHash(freezeFile)) throw new Error('R5 budget approval is not bound to this freeze file hash');
  if (JSON.stringify(record.caps) !== JSON.stringify(LOAD_R5_CAP_TABLE[record.decision]) || record.retry_granted !== (record.decision === 'approve' ? 1 : 0)) throw new Error('R5 budget approval caps differ from the reviewed table');
  return record;
}

// Only the two decisions that grant capacity are ever recorded; a reject (or anything else) writes nothing.
// The record is Jon's decision (253-83), never the executor's: this plan adds the recorder but never calls it against the real R5 files.
export function recordBudgetApprovalR5({ decision, budgetFile, freezeFile, outputFile, decisionText }, root = ROOT, { enforcePaths = true, now = () => new Date().toISOString() } = {}) {
  if (!Object.hasOwn(LOAD_R5_CAP_TABLE, decision ?? '')) throw new Error(`decision ${JSON.stringify(decision)} grants no capacity: only approve or approve-without-retry are recorded`);
  if (typeof decisionText !== 'string' || !decisionText.trim()) throw new Error('the approval record needs Jon\'s decision text verbatim');
  if (enforcePaths && (path.resolve(budgetFile) !== path.resolve(root, LOAD_R5_BUDGET_PATH) || path.resolve(freezeFile) !== path.resolve(root, LOAD_R5_FREEZE_PATH)
    || path.resolve(outputFile) !== path.resolve(root, LOAD_R5_APPROVAL_PATH))) throw new Error('budget approval must use the reviewed R5 budget, freeze and approval paths');
  const freeze = readJson(freezeFile);
  if (enforcePaths) validateLoadRecoveryFreezeR5(root, freeze);
  const budgetHash = fileHash(budgetFile);
  if (!budgetHash || freeze.budget?.sha256 !== budgetHash) throw new Error('the R5 budget document differs from the freeze binding');
  const record = {
    schema_version: LOAD_R5_APPROVAL_SCHEMA, decision, decided_by: 'Jon (operator), recorded by executor from checkpoint response', decision_text: decisionText,
    budget_sha256: budgetHash, freeze_sha256: fileHash(freezeFile), caps: { ...LOAD_R5_CAP_TABLE[decision] }, retry_granted: decision === 'approve' ? 1 : 0, recorded_at: now()
  };
  fs.mkdirSync(path.dirname(outputFile), { recursive: true });
  fs.writeFileSync(outputFile, `${JSON.stringify(record, null, 2)}\n`, { flag: 'wx' });
  return record;
}

export function initializeLoadRecoveryEvidenceR5(freezeFile, evidenceFile, root = ROOT, deps = {}) {
  const d = { validate: validateLoadRecoveryFreezeR5, readApproval: readCommittedApprovalR5, ...deps };
  if (fs.existsSync(evidenceFile)) throw new Error('refusing to overwrite additive R5 native load recovery evidence');
  const freeze = readJson(freezeFile);
  d.validate(root, freeze);
  const closed = [...freeze.historical.spent_reservations, ...freeze.historical.expired_identities, ...freeze.historical.retired_identities];
  const reused = freeze.ledger.slots.find((slot) => closed.includes(slot.id));
  if (reused) throw new Error(`slot ${reused.id} is a spent, expired or retired identity and can never run again`);
  const approval = d.readApproval(root, freezeFile, freeze);
  if (!Object.hasOwn(LOAD_R5_CAP_TABLE, approval?.decision ?? '')) throw new Error('R5 approval decision grants no capacity');
  const caps = LOAD_R5_CAP_TABLE[approval.decision];
  const evidence = {
    schema_version: LOAD_R5_SCHEMA, revision: 'r5', status: 'ready', context_identity: LOAD_R4_CONTEXT_MODE,
    freeze_path: path.relative(root, freezeFile), freeze_sha256: fileHash(freezeFile),
    source: structuredClone(freeze.source), historical: structuredClone(freeze.historical),
    carried_first_window: structuredClone(freeze.carried_first_window), account_count: structuredClone(freeze.account_count),
    created_at: new Date().toISOString(), attempts: [], preparation: null, reservation: null, preserved_revisions: [],
    prior_terminal_halts: [structuredClone(freeze.historical.terminal_halt)], infrastructure_halts: [], infrastructure_retry: null,
    approval: { decision: approval.decision, retry_granted: approval.retry_granted },
    limits: {
      prior_charge_ms: freeze.ledger.prior_charge_ms, preparation_charge_ms: 0, preparation_remaining_ms: freeze.ledger.preparation_reserve_ms,
      charged_duration_ms: freeze.ledger.prior_charge_ms, physical_playwright_cli_launches: freeze.ledger.prior_playwright_cli_launches,
      used_slots: [...freeze.ledger.spent_reservations], max_d19_ms: caps.d19_cap_ms, max_total_ms: caps.shared_cap_ms,
      max_d19_physical_playwright_cli_launches: caps.d19_launch_max, max_physical_playwright_cli_launches: caps.physical_cli_max,
      retry_used: 1, retry_available: 0, infra_retry: { granted: approval.retry_granted, used: 0 }
    }
  };
  fs.mkdirSync(`${evidenceFile}.raw`, { recursive: true });
  writeJson(evidenceFile, evidence);
  return evidence;
}

// ---- Phase 253 plan 80: R5 second-window run path, verifier, approval gates and terminal verification (additive; R4 stays untouched) ----
// Modeled on the R4 functions. Differences: R5 identities, paths, schemas and cap table; three second windows; the schema-qualified
// v2 account-count receipts with their redacted psql stderr sidecars; and the carried accepted first window, which is re-verified
// against the committed R4 bytes on every verify and joined to the new rows for the 22-row proof.
function loadR5AcceptedAttempts(evidence) {
  return evidence.attempts.filter((attempt) => attempt.observed_outcome === 'native_rows_accepted');
}

function loadR5EffectiveRetrySlot(slots, haltedId) {
  const halted = slots.slice(0, 3).find((slot) => slot.id === haltedId);
  if (!halted) throw new Error(`infrastructure retry has no frozen slot to re-run: ${haltedId}`);
  return { ...halted, id: LOAD_R5_RETRY_ID, maps_from: haltedId, retry: true, retry_of: haltedId };
}

// The shared Plan 39 predicates only understand the v1 count receipt, so they run on a projection of each accepted v2 receipt
// (v1 schema; database, digest, exit, count and monotonic fields only). The v2 receipt itself is judged first, against the freeze.
function accountReceiptProjectionR5(receipt) {
  if (!receipt || receipt.schema_version !== ACCOUNT_COUNT_SCHEMA_R5) return receipt;
  return {
    schema_version: ACCOUNT_COUNT_SCHEMA, database: receipt.database, account_email_sha256: receipt.account_email_sha256, exit_code: receipt.exit_code,
    timed_out: receipt.timed_out, error: receipt.error === null ? null : '<see the R5 receipt>', count: receipt.count,
    started_monotonic_ns: receipt.started_monotonic_ns, ended_monotonic_ns: receipt.ended_monotonic_ns
  };
}

function verifySidecarR5(attempt, reference, expectedSha256, baseDir, label) {
  const file = confinedFile(baseDir, reference);
  if (!file || !fs.existsSync(file)) return [`${label} psql stderr sidecar is missing from the raw receipts`];
  return fileHash(file) === reference.sha256 && reference.sha256 === expectedSha256 ? [] : [`${label} psql stderr sidecar differs from the receipt digest`];
}

export function verifyNativeLoadAttemptR5(attempt, freeze, baseDir) {
  const errors = [];
  if (!attempt || typeof attempt !== 'object') return { ok: false, errors: ['native load attempt is missing'] };
  let effective = freeze;
  if (attempt.slot_id === LOAD_R5_RETRY_ID) {
    try {
      const slot = loadR5EffectiveRetrySlot(freeze.ledger.slots, attempt.retry_of);
      effective = { ...freeze, ledger: { ...freeze.ledger, slots: [...freeze.ledger.slots.slice(0, 3), slot] } };
    } catch (error) { return { ok: false, errors: [error.message] }; }
  }
  const slot = effective.ledger.slots.find((item) => item.id === attempt.slot_id);
  const digest = slot?.collision_account_sha256?.[slot?.project];
  errors.push(...verifyAccountCountReceiptR5(attempt.prior_collision_absence, attempt, digest, 0, 'prior collision absence before browser work', freeze.account_count));
  errors.push(...verifyAccountCountReceiptR5(attempt.created_account, attempt, digest, 1, 'created account after registration', freeze.account_count));
  for (const name of ['prior_collision_absence', 'created_account']) {
    if (attempt[name]?.schema_version === ACCOUNT_COUNT_SCHEMA_R5) errors.push(...verifySidecarR5(attempt, attempt.files?.[`${name}_stderr`], attempt[name].stderr_sha256, baseDir, name.replaceAll('_', ' ')));
  }
  if (attempt.database?.absence_receipt) errors.push(...verifySidecarR5(attempt, attempt.files?.database_absence_stderr, attempt.database.absence_stderr_sidecar?.sha256, baseDir, 'database absence'));
  const adjusted = {
    ...attempt, charged_duration_ms: Math.max(attempt.execution_duration_ms ?? 0, attempt.wall_duration_ms ?? 0),
    prior_collision_absence: accountReceiptProjectionR5(attempt.prior_collision_absence), created_account: accountReceiptProjectionR5(attempt.created_account)
  };
  errors.push(...verifyNativeLoadAttempt(adjusted, effective, baseDir, { contextIdentity: LOAD_R4_CONTEXT_MODE }).errors);
  attempt.collision_receipts = adjusted.collision_receipts; attempt.fresh_state_receipts = adjusted.fresh_state_receipts;
  errors.push(...verifyAttemptAccountingR3(attempt, slot, baseDir), ...verifyHostAwakeR3(attempt));
  const unique = [...new Set(errors)];
  return { ok: unique.length === 0, errors: unique };
}

// The halted original of an infrastructure retry is not accepted proof, but it stays honest, charged and counted.
function verifyInfrastructureHaltedAttemptR5(attempt, freeze, baseDir) {
  const errors = [...verifyAttemptAccountingR3(attempt, (freeze?.ledger?.slots ?? []).find((item) => item.id === attempt.slot_id), baseDir), ...verifyHostAwakeR3(attempt)];
  const hostFault = attempt.host?.suspension_detected === true || attempt.host?.holder_alive_at_end === false;
  if (!hostFault) errors.push('infrastructure halt carries no host-sleep, lost-holder or host-failure evidence');
  if (attempt.assertion_failure_observed === true) errors.push('an observed assertion failure is never an infrastructure halt');
  if (!OWNED_CONTROL_DATABASE.test(attempt.database?.name ?? '')) errors.push('database identity is outside the synthetic control namespace');
  return errors;
}

// `carried` is the live re-verification of the carried first window (carriedFirstWindowR5 over the committed R4 bytes); it must
// equal both the frozen binding and the binding copied into the evidence, so a tampered binding fails in any of the three places.
export function verifyLoadRecoveryEvidenceDataR5(evidence, freeze, baseDir, stage = 'complete', freezeFileHash = freeze?.freeze_sha256, { carried = null } = {}) {
  const errors = [];
  if (!evidence || typeof evidence !== 'object' || Array.isArray(evidence)) return { ok: false, errors: ['R5 native load recovery evidence is missing or malformed'] };
  if (freeze?.schema_version !== LOAD_R5_FREEZE_SCHEMA || freeze.freeze_sha256 !== loadFreezeDigest(freeze) || evidence.freeze_sha256 !== freezeFileHash) errors.push('evidence does not match the immutable R5 load recovery freeze');
  if (evidence.schema_version !== LOAD_R5_SCHEMA || JSON.stringify(evidence.source) !== JSON.stringify(freeze?.source)) errors.push('evidence source identity differs from the frozen commit and blobs');
  if (evidence.context_identity !== LOAD_R4_CONTEXT_MODE || freeze?.context_identity !== LOAD_R4_CONTEXT_MODE) errors.push('evidence and freeze must carry the per_row_union context identity mode');
  const binding = freeze?.carried_first_window;
  if (!binding || canonicalJsonR5(evidence.carried_first_window) !== canonicalJsonR5(binding)) errors.push('evidence carried first window differs from the frozen binding');
  if (!carried || canonicalJsonR5(carried) !== canonicalJsonR5(binding)) errors.push('carried first window binding fails re-verification against the committed R4 bytes');
  if (!freeze?.account_count || canonicalJsonR5(evidence.account_count) !== canonicalJsonR5(freeze.account_count)) errors.push('evidence account count binding differs from the freeze');
  if (evidence.reservation || ['running', 'halted', 'halted_infrastructure'].includes(evidence.status)) errors.push('evidence contains an unresolved predebit reservation or a halted status');
  const caps = Object.hasOwn(LOAD_R5_CAP_TABLE, evidence.approval?.decision ?? '') ? LOAD_R5_CAP_TABLE[evidence.approval.decision] : null;
  if (!caps) errors.push('evidence carries no recognised budget approval decision');
  const limits = evidence.limits ?? {};
  if (limits.retry_used !== 1 || limits.retry_available !== 0) errors.push('the spent original retry was reopened or miscounted');
  if (limits.prior_charge_ms !== LOAD_R5_CARRIED_MS) errors.push('carried historical charge changed');
  if (caps && (limits.max_d19_ms !== caps.d19_cap_ms || limits.max_total_ms !== caps.shared_cap_ms || limits.max_physical_playwright_cli_launches !== caps.physical_cli_max
    || limits.max_d19_physical_playwright_cli_launches !== caps.d19_launch_max)) errors.push('approved time or physical CLI launch ceiling changed');
  if (JSON.stringify(evidence.prior_terminal_halts?.[0]) !== JSON.stringify(freeze?.historical?.terminal_halt)) errors.push('the 253-73 terminal non-infrastructure halt is not preserved in the ledger');
  const attempts = Array.isArray(evidence.attempts) ? evidence.attempts : [];
  // An infrastructure-halted original plus its accepted retry is one slot outcome; the original stays in attempts.
  const outcomes = []; const haltedOriginals = [];
  for (let index = 0; index < attempts.length; index += 1) {
    const attempt = attempts[index];
    if (attempt.observed_outcome !== 'halted_infrastructure') { outcomes.push(attempt); continue; }
    haltedOriginals.push(attempt);
    errors.push(...verifyInfrastructureHaltedAttemptR5(attempt, freeze, baseDir).map((message) => `${attempt.slot_id} (infrastructure halt): ${message}`));
    const retry = attempts[index + 1];
    if (!retry || retry.slot_id !== LOAD_R5_RETRY_ID || retry.retry_of !== attempt.slot_id) { errors.push(`infrastructure-halted ${attempt.slot_id} has no accepted ${LOAD_R5_RETRY_ID} outcome`); continue; }
    if (JSON.stringify(retry.argv) !== JSON.stringify(attempt.argv) || JSON.stringify(retry.projects) !== JSON.stringify(attempt.projects)) errors.push('the retry did not carry the identical frozen selection');
    outcomes.push(retry); index += 1;
  }
  const retryOutcomes = outcomes.filter((attempt) => attempt.slot_id === LOAD_R5_RETRY_ID);
  if (retryOutcomes.length !== haltedOriginals.length || retryOutcomes.length > 1) errors.push('at most one infrastructure retry, paired with one infrastructure-halted original, is allowed');
  if (retryOutcomes.length === 1) {
    const record = evidence.infrastructure_retry;
    if (evidence.approval?.retry_granted !== 1 || limits.infra_retry?.granted !== 1 || limits.infra_retry?.used !== 1) errors.push('the infrastructure retry was used without a granted, single-use approval');
    if (record?.used !== true || record.halted_slot !== retryOutcomes[0].retry_of || !/^[0-9a-f]{64}$/.test(record.diagnostic?.sha256 ?? '') || typeof record.diagnostic?.file !== 'string') errors.push('the infrastructure retry lacks its committed diagnostic record');
  } else if (limits.infra_retry?.used !== 0) errors.push('retry usage is recorded without a retry outcome');
  const progress = stage === 'progress' && outcomes.length <= 2;
  if (!progress && !(stage === 'complete' && outcomes.length === 3)) errors.push(`stage ${stage} requires ${stage === 'progress' ? '0 to 2' : stage === 'complete' ? 'exactly 3' : 'a progress or complete stage with'} accepted new native command outcomes, found ${outcomes.length}`);
  const slots = (freeze?.ledger?.slots ?? []).slice(0, 3);
  if (outcomes.some((attempt, index) => (attempt.slot_id === LOAD_R5_RETRY_ID ? attempt.retry_of : attempt.slot_id) !== slots[index]?.id)) errors.push('new commands do not match the exact unused reservation order');
  const closed = [...LOAD_R5_SPENT, ...LOAD_R5_EXPIRED.filter((id) => id !== LOAD_R5_RETRY_ID), ...LOAD_R5_RETIRED];
  if (attempts.some((attempt) => closed.includes(attempt.slot_id) || /^CR[1-4]?-/.test(attempt.slot_id ?? ''))) errors.push('a spent, expired or retired reservation, or an identity from an earlier revision, was reopened');
  const usedSlots = [...(freeze?.ledger?.spent_reservations ?? []), ...attempts.map((attempt) => attempt.slot_id)];
  if (JSON.stringify(limits.used_slots) !== JSON.stringify(usedSlots)) errors.push('used reservation ledger differs from historical receipts and actual attempts');
  const measured = (freeze?.ledger?.prior_charge_ms ?? 0) + attempts.reduce((sum, attempt) => sum + (Number(attempt.charged_duration_ms) || 0), 0) + (Number(limits.preparation_charge_ms) || 0);
  if (limits.charged_duration_ms !== measured) errors.push('cumulative charge does not equal preserved history, preparation and measured command receipts');
  if ((limits.preparation_charge_ms ?? 0) > LOAD_R3_PREPARATION_MS) errors.push('preparation exceeded its R5 reservation');
  const launches = (freeze?.ledger?.prior_playwright_cli_launches ?? 0) + attempts.filter((attempt) => attempt.playwright_cli?.launched === true).length;
  if (limits.physical_playwright_cli_launches !== launches || (caps && launches > caps.physical_cli_max)) errors.push('physical Playwright CLI launch count differs from native receipts or exceeds its approved ceiling');
  if (caps && (measured > caps.d19_cap_ms || measured > caps.shared_cap_ms)) errors.push('approved D-19 or shared time limit was exceeded');
  for (const attempt of outcomes) errors.push(...verifyNativeLoadAttemptR5(attempt, freeze, baseDir).errors.map((message) => `${attempt.slot_id}: ${message}`));
  // The carried first window and the new second windows are judged as one ledger: distinct databases, a fresh-state digest that
  // equals the carried collision receipt, and browser-context identities that are unique across the union of carried and new rows.
  attempts.forEach((attempt, index) => {
    if (attempts.slice(0, index).some((prior) => prior.database?.name === attempt.database?.name)) errors.push('two native slots reused the same physical database identity');
    if (binding?.database && attempt.database?.name === binding.database) errors.push('a new native slot reused the carried first window database');
  });
  for (const attempt of outcomes) {
    const prior = binding?.collision_receipts?.[attempt.project];
    if (!prior || prior !== attempt.fresh_state_receipts?.[attempt.project]) errors.push(`${attempt.project}: fresh database does not prove the prior collision account absent before recreating it`);
  }
  const contextRows = [];
  for (const attempt of outcomes) {
    const reportFile = confinedFile(baseDir, attempt.files?.playwright_report);
    if (!reportFile || !fs.existsSync(reportFile)) continue; // reported by the attempt verifier
    try { for (const result of playReportTests(readJson(reportFile))) contextRows.push({ label: `${attempt.slot_id} / ${result.project} / ${result.title}`, result }); } catch { /* reported by the attempt verifier */ }
  }
  errors.push(...crossRowContextReuseR4(contextRows));
  const carriedIds = new Set(binding?.context_ids ?? []);
  if (contextRows.some((row) => controlContextIdentitiesR4(row.result).some((id) => carriedIds.has(id)))) errors.push('a new row reused a browser-context identity carried from the first window');
  if (stage === 'complete') {
    const total = outcomes.reduce((sum, attempt) => sum + (attempt.lifecycle?.rows ?? 0), 0) + (Number(binding?.rows) || 0);
    if (total !== 22) errors.push(`native rows total ${total} (carried ${binding?.rows ?? 0} plus new), the complete proof requires 22`);
  }
  const expectedStatus = stage === 'complete' ? 'complete' : outcomes.length === 0 ? 'ready' : 'second_partial';
  if (evidence.status !== expectedStatus) errors.push(`evidence status ${evidence.status} does not match ${outcomes.length} accepted new outcomes (expected ${expectedStatus})`);
  return { ok: errors.length === 0, errors };
}

export function verifyLoadRecoveryFileR5(evidenceFile, stage, root = ROOT, deps = {}) {
  const d = { carriedFirst: carriedFirstWindowR5, validate: validateLoadRecoveryFreezeR5, ...deps };
  try {
    if (path.resolve(evidenceFile) !== path.resolve(root, LOAD_R5_EVIDENCE_PATH)) throw new Error('verification accepts only the additive R5 native evidence path');
    const evidence = readJson(evidenceFile);
    const freezeFile = path.resolve(root, evidence.freeze_path ?? '');
    if (freezeFile !== path.resolve(root, LOAD_R5_FREEZE_PATH)) throw new Error('native evidence does not point to the reviewed R5 freeze');
    const freeze = readJson(freezeFile);
    d.validate(root, freeze, { terminal: ['second_partial', 'complete'].includes(evidence.status) });
    let carried = null;
    try { carried = d.carriedFirst(root); } catch (error) { throw new Error(`carried first window binding fails re-verification: ${error.message}`); }
    const result = verifyLoadRecoveryEvidenceDataR5(evidence, freeze, `${evidenceFile}.raw`, stage, fileHash(freezeFile), { carried });
    if (!result.ok) console.error(`R5 native load recovery evidence rejected:\n- ${result.errors.join('\n- ')}`);
    else console.log(`R5 native load recovery verified: ${evidence.attempts.length} new commands; ${evidence.limits.physical_playwright_cli_launches}/${evidence.limits.max_physical_playwright_cli_launches} CLI launches; ${evidence.limits.charged_duration_ms} ms cumulative; retry_available=0`);
    return result;
  } catch (error) { console.error(`R5 native load recovery evidence rejected: ${error.message}`); return { ok: false, errors: [error.message] }; }
}

// ---- 253-84: load acceptance verifier and honest target predicate (D-04/D-20/D-24) ----
const LOAD_ACCEPT_SCHEMA = 'sigra.phase253.load-acceptance-evidence/v1';
const LOAD_ACCEPT_FREEZE_PATH = `${PHASE_DIR}/253-LOAD-RECOVERY-ACCEPTANCE-FREEZE.json`;
const LOAD_ACCEPT_EVIDENCE_PATH = `${PHASE_DIR}/253-LOAD-RECOVERY-ACCEPTANCE-EVIDENCE.json`;
// Each repair proves only its own defect. None of these classes can ever be the historical registration cause.
const LOAD_ACCEPT_RUNNER_REPAIR_CLASSES = [
  'node20_loader_collection', 'control_port_mismatch', 'host_sleep_runner', 'r3_control_design', 'r3_library_enumeration',
  'r3_deadline_sizing', 'r3_diagnostics', 'r4_validator_double_count', 'r5_account_count_query', 'exhausted_budget', 'current_passing_diagnostic'
];
const LOAD_ACCEPT_CAUSAL_REPAIR_CLASSES = ['registration_harness_seam', 'registration_test_defect', 'registration_ci_defect'];
const LOAD_ACCEPT_PROJECTS = ['admin-eval', 'admin-eval-mobile', 'admin-eval-dark'];
const LOAD_ACCEPT_IDS = LOAD_ACCEPT_PROJECTS.flatMap((project) => [1, 2, 3].map((repeat) => `D20-ACCEPT-${project}-${repeat}`));
const LOAD_ACCEPT_STATUSES = ['diagnosis_incomplete', 'ready', 'running', 'halted', 'complete'];

function acceptanceSourceErrors(root, ref, label) {
  const errors = [];
  if (!ref || typeof ref.path !== 'string' || !/^[0-9a-f]{64}$/.test(ref.sha256 ?? '')) return [`${label} lacks a path and sha256`];
  const file = path.resolve(root, ref.path);
  if (file !== root && !file.startsWith(`${root}${path.sep}`)) return [`${label} escapes the repository`];
  if (fileHash(file) !== ref.sha256) errors.push(`${label} does not reopen at its recorded sha256`);
  return errors;
}

export function verifyLoadAcceptanceData(evidence, { root = ROOT, stage = 'complete', requireTarget = false, verifyControls = null } = {}) {
  const errors = [];
  if (!evidence || typeof evidence !== 'object' || Array.isArray(evidence)) return { ok: false, errors: ['load acceptance evidence is missing or malformed'] };
  if (evidence.schema_version !== LOAD_ACCEPT_SCHEMA) errors.push('load acceptance schema mismatch');
  if (!LOAD_ACCEPT_STATUSES.includes(evidence.status)) errors.push('load acceptance status is unknown');
  if (!['open', 'accepted'].includes(evidence.target_status)) errors.push('target_status must be open or accepted');
  if (evidence.integration_pending !== true) errors.push('PR integration and phase verification must remain integration_pending');
  // The completed R5 controls are re-opened, never trusted from an embedded claim.
  const controls = evidence.controls;
  if (controls?.path !== LOAD_R5_EVIDENCE_PATH || controls?.stage !== 'complete') errors.push('controls must link the R5 native evidence at stage complete');
  else {
    errors.push(...acceptanceSourceErrors(root, controls, 'R5 controls evidence'));
    const reopen = verifyControls ?? (() => verifyLoadRecoveryFileR5(path.resolve(root, LOAD_R5_EVIDENCE_PATH), 'complete', root).ok);
    let reopened = false;
    try { reopened = reopen() === true; } catch { reopened = false; }
    if (!reopened) errors.push('the R5 controls evidence does not reopen as complete');
  }
  for (const [index, source] of (evidence.observed_cause?.sources ?? []).entries()) errors.push(...acceptanceSourceErrors(root, source, `observed_cause source ${index}`));
  if (!Array.isArray(evidence.observed_cause?.sources) || evidence.observed_cause.sources.length === 0) errors.push('observed_cause must cite reopenable sources');
  const known = new Set([...LOAD_ACCEPT_RUNNER_REPAIR_CLASSES, ...LOAD_ACCEPT_CAUSAL_REPAIR_CLASSES]);
  for (const repair of Array.isArray(evidence.repairs) ? evidence.repairs : []) {
    if (!known.has(repair?.defect_class)) errors.push(`repair ${repair?.id} has an unknown defect class`);
    if (repair?.explains_historical_cause !== false) errors.push(`repair ${repair?.id} claims or omits whether it explains the historical cause; a repair proves only its own defect`);
    errors.push(...acceptanceSourceErrors(root, repair?.source, `repair ${repair?.id} source`));
  }
  if (!Array.isArray(evidence.repairs)) errors.push('repairs must be a list');
  const cause = evidence.historical_cause;
  let demonstrated = false;
  if (!cause || !['diagnosis_incomplete', 'not_reproduced', 'demonstrated'].includes(cause.status)) errors.push('historical_cause status is unknown');
  else if (cause.status === 'demonstrated') {
    // A caller boolean is never trusted: only a re-opened red-before / repair / green-after link counts.
    const link = cause.causal_link;
    const before = errors.length;
    if (!link) errors.push('a demonstrated cause requires a causal red/repair/green link');
    else {
      errors.push(...acceptanceSourceErrors(root, link.original, 'original failure record'));
      if (typeof link.seam !== 'string' || link.seam.length < 8) errors.push('the responsible harness seam is not identified');
      const red = link.red; const repair = link.repair; const green = link.green;
      if (!/^[0-9a-f]{40}$/.test(red?.source_blob ?? '') || red?.before_repair !== true || !Number.isInteger(red?.exit_code) || red.exit_code === 0) errors.push('the red-before counterexample must fail on preserved exact source');
      errors.push(...acceptanceSourceErrors(root, red?.receipt, 'red receipt'));
      if (!LOAD_ACCEPT_CAUSAL_REPAIR_CLASSES.includes(repair?.defect_class)) errors.push('the repair is a runner/infrastructure repair or unknown class and cannot be the historical cause');
      if (!/^[0-9a-f]{40}$/.test(repair?.source_blob ?? '') || !/^[0-9a-f]{64}$/.test(repair?.diff_sha256 ?? '')) errors.push('the repair lacks source blob and diff hashes');
      if (green?.exit_code !== 0 || green?.source_blob !== repair?.source_blob) errors.push('the green-after run must pass on the repaired source');
      errors.push(...acceptanceSourceErrors(root, green?.receipt, 'green receipt'));
    }
    demonstrated = errors.length === before;
  }
  const acceptance = evidence.acceptance ?? {};
  const attempts = Array.isArray(acceptance.attempts) ? acceptance.attempts : [];
  if (JSON.stringify(acceptance.reserved_ids) !== JSON.stringify(LOAD_ACCEPT_IDS)) errors.push('the nine D-20 acceptance reservations changed');
  if (acceptance.retry_available !== 0) errors.push('acceptance has no retry');
  if (attempts.length > 0 && !demonstrated) errors.push('no proved cause means no acceptance launch');
  if (attempts.length > 0) {
    errors.push(...acceptanceSourceErrors(root, acceptance.freeze, 'acceptance freeze'));
    const seen = new Set();
    let lastIndex = -1;
    for (const attempt of attempts) {
      const index = LOAD_ACCEPT_IDS.indexOf(attempt?.id);
      if (index < 0 || seen.has(attempt.id)) errors.push(`acceptance ID ${attempt?.id} is unknown or reused`);
      if (index <= lastIndex) errors.push(`acceptance ID ${attempt?.id} is out of frozen order`);
      lastIndex = Math.max(lastIndex, index); seen.add(attempt?.id);
      if (attempt?.outcome !== 'passed' || attempt.fresh !== true || attempt.host_awake !== true || !(attempt.charged_duration_ms > 0 && attempt.charged_duration_ms <= 240_000)) errors.push(`acceptance attempt ${attempt?.id} is not a fresh awake pass within 240000 ms`);
    }
  }
  if (evidence.target_status === 'accepted') {
    if (!demonstrated) errors.push('an accepted target requires a demonstrated cause');
    if (evidence.status !== 'complete') errors.push('an accepted target requires a complete record');
    const affected = acceptance.affected_projects;
    if (!Array.isArray(affected) || affected.length === 0 || affected.some((project) => !LOAD_ACCEPT_PROJECTS.includes(project))) errors.push('the affected project subset is missing or unknown');
    else {
      const expected = LOAD_ACCEPT_IDS.filter((id) => affected.some((project) => id.startsWith(`D20-ACCEPT-${project}-`)));
      if (JSON.stringify(attempts.map((attempt) => attempt.id)) !== JSON.stringify(expected)) errors.push('accepted target needs exactly three fresh passes per affected project in frozen order');
      if (attempts.some((attempt) => attempt.project !== String(attempt.id).replace(/^D20-ACCEPT-/, '').replace(/-\d$/, ''))) errors.push('an acceptance attempt project differs from its reservation');
    }
  }
  const accepted = errors.length === 0 && evidence.target_status === 'accepted';
  if (requireTarget && !accepted) errors.push(`the target is not accepted (target_status ${evidence.target_status}, historical cause ${cause?.status ?? 'unknown'})`);
  if (stage === 'complete' && evidence.target_status !== 'accepted') errors.push('stage complete requires a resolved target');
  return { ok: errors.length === 0, errors };
}

export function verifyLoadAcceptanceFile(evidenceFile, stage, requireTarget, root = ROOT, deps = {}) {
  try {
    if (path.resolve(evidenceFile) !== path.resolve(root, LOAD_ACCEPT_EVIDENCE_PATH)) throw new Error('verification accepts only the reviewed load acceptance evidence path');
    const result = verifyLoadAcceptanceData(readJson(evidenceFile), { root, stage, requireTarget, ...deps });
    if (!result.ok) console.error(`load acceptance evidence rejected:\n- ${result.errors.join('\n- ')}`);
    else console.log(`load acceptance verified at stage ${stage}${requireTarget ? ' (target accepted)' : ''}`);
    return result;
  } catch (error) { console.error(`load acceptance evidence rejected: ${error.message}`); return { ok: false, errors: [error.message] }; }
}

// ---- 253-89: honest, human-approved not_reproduced target disposition (D-04/D-24) ----
const LOAD_DISPOSITION_PATH = `${PHASE_DIR}/253-LOAD-RECOVERY-TARGET-DISPOSITION.json`;
const LOAD_DISPOSITION_APPROVAL_PATH = `${PHASE_DIR}/253-LOAD-RECOVERY-TARGET-DISPOSITION-APPROVAL.json`;
const LOAD_DISPOSITION_SCHEMA = 'sigra.phase253.load-target-disposition/v1';
const LOAD_DISPOSITION_APPROVAL_SCHEMA = 'sigra.phase253.load-target-disposition-approval/v1';
const LOAD_DISPOSITION_TARGET = 'admin-eval registration (D-03): admin-eval, admin-eval-mobile, admin-eval-dark';
const LOAD_DISPOSITION_BASELINE_RUNS = ['38139851334', '38141796613', '38205503164'];
// The five harness-only repair groups. Each explains only its own defect, never the historical cause.
const LOAD_DISPOSITION_REPAIR_GROUPS = [
  { group: 'node20-loader', classes: ['node20_loader_collection'] },
  { group: '253-40-host-sleep', classes: ['host_sleep_runner'] },
  { group: 'r3-control-library-deadline-diagnostics', classes: ['r3_control_design', 'r3_library_enumeration', 'r3_deadline_sizing', 'r3_diagnostics'] },
  { group: 'r4-annotation-double-count', classes: ['r4_validator_double_count'] },
  { group: 'r5-schema-qualified-count', classes: ['r5_account_count_query'] }
];
const sameJson = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const gitCommitted = {
  tracked: (root, rel) => run('git', ['-C', root, 'ls-files', '--error-unmatch', '--', rel]).status === 0,
  inHead: (root, rel) => run('git', ['-C', root, 'cat-file', '-e', `HEAD:${rel}`]).status === 0,
  headBytes: (root, rel) => readGitBlob(root, `HEAD:${rel}`)
};

function dispositionEvidenceErrors(evidence, root, verifyControls) {
  const errors = [];
  const base = verifyLoadAcceptanceData(evidence, { root, stage: 'progress', requireTarget: false, verifyControls });
  errors.push(...base.errors);
  if (evidence?.target_status !== 'open') errors.push('the disposition applies only to an open target');
  if (evidence?.historical_cause?.status !== 'diagnosis_incomplete') errors.push('the disposition requires historical_cause diagnosis_incomplete');
  if ((evidence?.acceptance?.attempts ?? []).length !== 0) errors.push('the disposition requires zero acceptance attempts');
  return errors;
}

export function createTargetDisposition({ evidenceFile, outputFile }, root = ROOT, { enforcePaths = true, now = () => new Date().toISOString(), verifyControls = null } = {}) {
  if (enforcePaths && (path.resolve(evidenceFile) !== path.resolve(root, LOAD_ACCEPT_EVIDENCE_PATH) || path.resolve(outputFile) !== path.resolve(root, LOAD_DISPOSITION_PATH))) {
    throw new Error('target disposition must use the reviewed acceptance evidence and disposition paths');
  }
  const evidence = readJson(evidenceFile);
  const errors = dispositionEvidenceErrors(evidence, root, verifyControls);
  if (errors.length > 0) throw new Error(`the acceptance evidence cannot be dispositioned (needs an open, diagnosis_incomplete record at stage progress with no attempts): ${errors.join('; ')}`);
  const repairs = Array.isArray(evidence.repairs) ? evidence.repairs : [];
  const record = {
    schema_version: LOAD_DISPOSITION_SCHEMA,
    target: LOAD_DISPOSITION_TARGET,
    status: 'not_reproduced',
    disposition_kind: 'human_approved_not_reproduced',
    automatic: false,
    created_at: now(),
    acceptance_evidence: { path: path.relative(root, evidenceFile).split(path.sep).join('/'), sha256: fileHash(evidenceFile) },
    controls: { path: evidence.controls.path, sha256: evidence.controls.sha256, stage: evidence.controls.stage, rows: 22 },
    historical_cause: { status: 'diagnosis_incomplete', cause: null, causal_link: null, missing: [...evidence.historical_cause.missing] },
    supporting_evidence_not_proof: {
      repairs: LOAD_DISPOSITION_REPAIR_GROUPS
        .map(({ group, classes }) => ({ group, repair_ids: repairs.filter((repair) => classes.includes(repair.defect_class)).map((repair) => repair.id), explains_historical_cause: false }))
        .filter((entry) => entry.repair_ids.length > 0),
      controls: { description: 'R5 native readiness/isolation controls accepted 22/22', path: evidence.controls.path, sha256: evidence.controls.sha256, proves_historical_cause: false }
    },
    acceptance_slots: LOAD_ACCEPT_IDS.map((id) => ({ id, status: 'expired_unused' })),
    requirements: {
      'CIREL-01': {
        status: 'partial', satisfied: false,
        unmet: ['selected flaky failures reproduced', 'fixed with deterministic regression checks and repeat runs'],
        met: ['no increased blanket retries', 'readiness asserted without sleeps', '22/22 deterministic readiness/isolation controls'],
        amended: false
      },
      'CIREL-02': { status: 'not_decided_by_this_record' }
    },
    roadmap_sc1_no_flake_clause: {
      applies: false, qualifies_as_no_flake: false, automatic: false,
      reason: `The Phase 252 baseline retained registration failures (D-03 runs ${LOAD_DISPOSITION_BASELINE_RUNS.join(', ')}), so the no-flake clause does not apply.`
    },
    qualifies_as_no_flake: false
  };
  fs.mkdirSync(path.dirname(outputFile), { recursive: true });
  fs.writeFileSync(outputFile, `${JSON.stringify(record, null, 2)}\n`, { flag: 'wx' });
  return record;
}

// Only an explicit approve is recorded; reject or a reproduction hunt writes nothing.
export function recordTargetDispositionApproval({ decision, dispositionFile, outputFile, decisionText }, root = ROOT, { enforcePaths = true, now = () => new Date().toISOString() } = {}) {
  if (decision !== 'approve') throw new Error(`decision ${JSON.stringify(decision)} is not recorded: only approve writes a disposition approval`);
  if (enforcePaths && (path.resolve(dispositionFile) !== path.resolve(root, LOAD_DISPOSITION_PATH) || path.resolve(outputFile) !== path.resolve(root, LOAD_DISPOSITION_APPROVAL_PATH))) {
    throw new Error('disposition approval must use the reviewed disposition and approval path');
  }
  const disposition = readJson(dispositionFile);
  if (disposition.schema_version !== LOAD_DISPOSITION_SCHEMA) throw new Error('the disposition schema is not recognised');
  const record = {
    schema_version: LOAD_DISPOSITION_APPROVAL_SCHEMA, decision, decided_by: 'Jon (operator), recorded by executor from checkpoint response',
    decision_text: typeof decisionText === 'string' && decisionText.trim() ? decisionText : decision,
    disposition_sha256: fileHash(dispositionFile), acceptance_evidence_sha256: disposition.acceptance_evidence?.sha256 ?? null, recorded_at: now()
  };
  fs.mkdirSync(path.dirname(outputFile), { recursive: true });
  fs.writeFileSync(outputFile, `${JSON.stringify(record, null, 2)}\n`, { flag: 'wx' });
  return record;
}

export function verifyTargetDispositionData(evidence, disposition, approval, { root = ROOT, evidenceSha256, dispositionSha256, verifyControls = null } = {}) {
  const errors = dispositionEvidenceErrors(evidence, root, verifyControls);
  const d = disposition;
  if (!d || typeof d !== 'object' || d.schema_version !== LOAD_DISPOSITION_SCHEMA) errors.push('disposition schema mismatch');
  else {
    if (d.status !== 'not_reproduced' || d.disposition_kind !== 'human_approved_not_reproduced') errors.push('disposition status must be human-approved not_reproduced');
    if (d.automatic !== false || d.qualifies_as_no_flake !== false) errors.push('a disposition is never automatic and never qualifies as no-flake');
    if (d.acceptance_evidence?.sha256 !== evidenceSha256) errors.push('the disposition is not bound to the current acceptance evidence bytes');
    if (d.controls?.sha256 !== evidence?.controls?.sha256 || d.controls?.path !== evidence?.controls?.path) errors.push('the disposition is not bound to the R5 controls');
    const cause = d.historical_cause;
    if (cause?.status !== 'diagnosis_incomplete' || cause.cause !== null || cause.causal_link !== null) errors.push('the disposition must not claim a historical cause or causal link');
    if (!sameJson(cause?.missing, evidence?.historical_cause?.missing) || !Array.isArray(cause?.missing) || cause.missing.length === 0) errors.push('the disposition must carry the missing evidence verbatim');
    const req = d.requirements?.['CIREL-01'];
    if (req?.status !== 'partial' || req.satisfied !== false) errors.push('CIREL-01 must be recorded partial with satisfied false');
    const sc1 = d.roadmap_sc1_no_flake_clause;
    if (sc1?.applies !== false || sc1.qualifies_as_no_flake === true || sc1.automatic === true) errors.push('ROADMAP SC-1 no-flake clause must not apply');
    if (!sameJson((d.acceptance_slots ?? []).map((slot) => slot?.id), LOAD_ACCEPT_IDS) || (d.acceptance_slots ?? []).some((slot) => slot?.status !== 'expired_unused')) errors.push('the nine D-20 acceptance slots must all be expired_unused');
    if (Object.hasOwn(d, 'acceptance_attempts') && (d.acceptance_attempts ?? []).length > 0) errors.push('a disposition carries no acceptance attempts');
    for (const group of d.supporting_evidence_not_proof?.repairs ?? []) if (group?.explains_historical_cause !== false) errors.push('supporting repairs must not explain the historical cause');
  }
  if (!approval || approval.schema_version !== LOAD_DISPOSITION_APPROVAL_SCHEMA) errors.push('disposition approval schema mismatch');
  else {
    if (approval.decision !== 'approve') errors.push('the disposition approval decision is not approve');
    if (approval.disposition_sha256 !== dispositionSha256) errors.push('the approval is not bound to the disposition bytes');
    if (approval.acceptance_evidence_sha256 !== evidenceSha256) errors.push('the approval is not bound to the acceptance evidence bytes');
  }
  return { ok: errors.length === 0, errors };
}

function readCommittedJson(root, rel, git, label) {
  const file = path.join(root, rel);
  if (!fs.existsSync(file)) throw new Error(`${label} is absent`);
  if (!git.tracked(root, rel) || !git.inHead(root, rel)) throw new Error(`${label} is not committed in HEAD`);
  const bytes = fs.readFileSync(file);
  if (!bytes.equals(git.headBytes(root, rel))) throw new Error(`${label} differs from its committed bytes`);
  return { bytes, value: JSON.parse(bytes.toString('utf8')), sha256: sha256(bytes) };
}

// Exit 0 iff the target is accepted, or an approved, committed, hash-bound not_reproduced disposition exists.
export function verifyRequireTargetDisposition(evidenceFile, root = ROOT, deps = {}) {
  const verifyControls = deps.verifyControls ?? null;
  const git = deps.git ?? gitCommitted;
  try {
    if (path.resolve(evidenceFile) !== path.resolve(root, LOAD_ACCEPT_EVIDENCE_PATH)) throw new Error('verification accepts only the reviewed load acceptance evidence path');
    const evidence = readJson(evidenceFile);
    const accepted = verifyLoadAcceptanceData(evidence, { root, stage: 'complete', requireTarget: true, verifyControls });
    if (accepted.ok) { console.log('target resolved by route: accepted'); return { ok: true, errors: [], route: 'accepted' }; }
    const disposition = readCommittedJson(root, LOAD_DISPOSITION_PATH, git, 'target disposition');
    const approval = readCommittedJson(root, LOAD_DISPOSITION_APPROVAL_PATH, git, 'target disposition approval');
    const result = verifyTargetDispositionData(evidence, disposition.value, approval.value, { root, evidenceSha256: fileHash(evidenceFile), dispositionSha256: disposition.sha256, verifyControls });
    if (!result.ok) { console.error(`target disposition rejected:\n- ${result.errors.join('\n- ')}`); return result; }
    console.log('target resolved by route: disposition (human-approved not_reproduced; CIREL-01 partial)');
    return { ...result, route: 'disposition' };
  } catch (error) { console.error(`target disposition rejected: ${error.message}`); return { ok: false, errors: [error.message] }; }
}

export const loadR5RunDefaults = Object.freeze({
  validate: validateLoadRecoveryFreezeR5, runTree: runLoggedTree, spawnApp: spawn, waitReady, portAvailable, stopApp,
  probeHost: probeHostSleepSafety, readApproval: readCommittedApprovalR5, checkDiagnostic: readCommittedDiagnostic, holderAlive: processAlive, diagnosticFile: null,
  captureAbsence: captureOwnedDatabaseAbsenceR5, captureAccount: captureOwnedAccountCountR5, sanitizeTrace: sanitizeTraceFile, psqlRun: null,
  monotonicNs: () => process.hrtime.bigint(), wallMs: () => Date.now(),
  skipPreservation: false, enforcePaths: true, enforceNode: true
});

// Bounded preparation: toolchain version probes only (no app boot, warmup, Playwright CLI, or browser install).
export async function prepareLoadRecoveryR5(freezeFile, evidenceFile, root = ROOT, deps = {}) {
  const d = { validate: validateLoadRecoveryFreezeR5, readApproval: readCommittedApprovalR5, runTree: runLoggedTree, ...deps };
  const freeze = readJson(freezeFile);
  d.validate(root, freeze);
  d.readApproval(root, freezeFile, freeze);
  const evidence = readJson(evidenceFile);
  if (evidence.schema_version !== LOAD_R5_SCHEMA || evidence.freeze_sha256 !== fileHash(freezeFile)) throw new Error('evidence does not match the committed R5 freeze');
  if (evidence.status !== 'ready' || evidence.reservation || evidence.preparation) throw new Error('preparation is only available once, from ready evidence');
  if (evidence.attempts.length || evidence.limits.physical_playwright_cli_launches !== freeze.ledger.prior_playwright_cli_launches) throw new Error('preparation must precede every new native command');
  const reserve = evidence.limits.preparation_remaining_ms;
  evidence.status = 'running';
  evidence.reservation = { kind: 'preparation', reserved_ms: reserve, predebited_at: new Date().toISOString() };
  writeLoadRecoveryEvidence(evidenceFile, root, evidence, d);
  const dir = path.join(`${evidenceFile}.raw`, 'preparation'); fs.mkdirSync(dir, { recursive: true });
  const exampleDir = path.join(root, 'test/example'); const env = { ...process.env, MIX_ENV: 'dev' };
  const commands = [['mix_version', 'mix', ['--version']], ['host_dependency_versions', 'mix', ['deps']]];
  const started = process.hrtime.bigint(); const receipts = []; let failed = null;
  for (const [name, program, args] of commands) {
    const remaining = reserve - Math.ceil(Number(process.hrtime.bigint() - started) / 1e6);
    if (remaining <= 0) { failed = 'preparation reached its predebited allowance'; break; }
    const log = path.join(dir, `${name}.log`);
    const result = await d.runTree(program, args, exampleDir, env, log, remaining);
    receipts.push({ name, argv: [program, ...args], exit_code: result.exit_code, duration_ms: result.duration_ms, log: referenceFor(`${evidenceFile}.raw`, log) });
    if (result.exit_code !== 0 || result.timed_out) { failed = `${name} failed`; break; }
  }
  const duration = Math.ceil(Number(process.hrtime.bigint() - started) / 1e6);
  evidence.reservation = null; evidence.preparation = { receipts, duration_ms: duration, status: failed ? 'failed' : 'passed' };
  evidence.limits.preparation_charge_ms = duration; evidence.limits.preparation_remaining_ms = Math.max(0, reserve - duration);
  evidence.limits.charged_duration_ms += duration;
  evidence.status = failed || duration > reserve ? 'halted' : 'ready';
  if (evidence.status === 'halted') evidence.stop_reason = failed ?? 'preparation exceeded its allowance';
  writeLoadRecoveryEvidence(evidenceFile, root, evidence, d);
  if (evidence.status === 'halted') throw new Error(evidence.stop_reason);
  return { status: evidence.status, preparation_charge_ms: duration };
}

export async function runLoadRecoverySlotR5(freezeFile, slotId, evidenceFile, root = ROOT, deps = {}) {
  const d = { ...loadR5RunDefaults, ...deps };
  if (LOAD_R5_SPENT.includes(slotId)) throw new Error(`reservation ${slotId} is permanently spent and cannot be run or retried`);
  if (LOAD_R5_EXPIRED.includes(slotId)) throw new Error(`reservation ${slotId} is expired and can never be charged or run`);
  if (LOAD_R5_RETIRED.includes(slotId)) throw new Error(`reservation ${slotId} is retired unused and can never be run`);
  if (/^CR[1-4]?-/.test(slotId)) throw new Error(`reservation ${slotId} belongs to an earlier revision and can never be run by R5`);
  if (d.enforcePaths && (path.resolve(freezeFile) !== path.resolve(root, LOAD_R5_FREEZE_PATH) || path.resolve(evidenceFile) !== path.resolve(root, LOAD_R5_EVIDENCE_PATH))) throw new Error('R5 load recovery accepts only the reviewed R5 freeze and additive R5 evidence paths');
  if (d.enforceNode && process.version !== LOAD_NODE) throw new Error(`load recovery native commands require Node ${LOAD_NODE}`);
  const freeze = readJson(freezeFile);
  const freezeHash = fileHash(freezeFile);
  const regular = freeze.ledger?.slots?.slice(0, 3) ?? [];
  const isRetry = slotId === LOAD_R5_RETRY_ID;
  let slot = regular.find((item) => item.id === slotId);
  if (!slot && !isRetry) throw new Error('only the three frozen unused R5 load recovery slots and the one infrastructure retry may run');
  d.validate(root, freeze);
  const approval = d.readApproval(root, freezeFile, freeze);
  const caps = Object.hasOwn(LOAD_R5_CAP_TABLE, approval.decision ?? '') ? LOAD_R5_CAP_TABLE[approval.decision] : null;
  if (!caps) throw new Error('budget approval carries an unknown decision');
  if (approval.schema_version !== LOAD_R5_APPROVAL_SCHEMA || JSON.stringify(approval.caps) !== JSON.stringify(caps)) throw new Error('budget approval is not an R5 (v4) record: approval caps differ from the reviewed R5 table');
  if (!fs.existsSync(evidenceFile)) throw new Error('R5 native load recovery evidence must be initialized and committed before launch');
  const evidence = readJson(evidenceFile);
  if (evidence.schema_version !== LOAD_R5_SCHEMA || evidence.freeze_sha256 !== freezeHash) throw new Error('R5 native load evidence does not match the committed freeze');
  const limits = evidence.limits;
  let diagnostic = null;
  if (isRetry) {
    if (evidence.status !== 'halted_infrastructure' || evidence.reservation) throw new Error(`the infrastructure retry needs halted_infrastructure evidence, found ${evidence.status}`);
    if (limits.used_slots.includes(LOAD_R5_RETRY_ID) || limits.infra_retry?.used !== 0 || evidence.infrastructure_retry?.used || !evidence.infrastructure_retry?.eligible) throw new Error('the infrastructure retry was already used or is not eligible');
    if (approval.retry_granted !== 1 || limits.infra_retry.granted !== 1) throw new Error('the approved budget grants no infrastructure retry');
    slot = loadR5EffectiveRetrySlot(freeze.ledger.slots, evidence.infrastructure_retry.halted_slot);
  } else {
    if (!['ready', 'second_partial'].includes(evidence.status) || evidence.reservation) throw new Error(`refusing to use terminal or reserved R5 recovery evidence: ${evidence.status}`);
    if (limits.used_slots.includes(slot.id)) throw new Error(`reservation ${slot.id} was already consumed`);
  }
  if (limits.retry_used !== 1 || limits.retry_available !== 0 || limits.prior_charge_ms !== freeze.ledger.prior_charge_ms
    || limits.charged_duration_ms < freeze.ledger.prior_charge_ms) throw new Error('counter reset or reopened retry detected before setup');
  if (limits.max_d19_ms !== Math.min(caps.d19_cap_ms, freeze.ledger.caps.approve.d19_cap_ms) || limits.max_total_ms !== Math.min(caps.shared_cap_ms, freeze.ledger.caps.approve.shared_cap_ms)
    || limits.max_physical_playwright_cli_launches !== caps.physical_cli_max) throw new Error('approval caps differ from the evidence ledger');
  const accepted = loadR5AcceptedAttempts(evidence);
  const pending = regular.slice(accepted.length);
  if (!pending[0] || pending[0].id !== (isRetry ? slot.retry_of : slot.id)) throw new Error('slots must run in frozen order, each exactly once');
  // Checked after the free refusals above and before any spawn or charge.
  if (isRetry) diagnostic = d.checkDiagnostic(root, d.diagnosticFile);
  // The retry re-runs the halted slot in place, so its own window replaces that slot's reservation.
  const reservedSlots = isRetry ? [slot, ...pending.slice(1)] : pending;
  const retryReserved = !isRetry && approval.retry_granted === 1 && limits.infra_retry?.used === 0 ? freeze.ledger.slots[3].max_duration_ms : 0;
  const reservedMs = reservedSlots.reduce((sum, item) => sum + item.max_duration_ms, 0) + retryReserved;
  const reservedLaunches = reservedSlots.length + (retryReserved ? 1 : 0);
  if (slot.max_duration_ms !== slot.setup_ms + slot.command_ms || slot.command_ms !== slot.work_ms + slot.cleanup_ms
    || limits.charged_duration_ms + limits.preparation_remaining_ms + reservedMs > limits.max_d19_ms
    || limits.physical_playwright_cli_launches + reservedLaunches > limits.max_d19_physical_playwright_cli_launches
    || limits.charged_duration_ms + limits.preparation_remaining_ms + reservedMs + 9 * 240000 + 3 * 60000 > limits.max_total_ms
    || limits.physical_playwright_cli_launches + reservedLaunches + 9 > limits.max_physical_playwright_cli_launches) throw new Error('remaining D-19 and conditional D-20 reservations do not fit approved limits');
  if (!(await d.portAvailable(slot.port))) throw new Error(`frozen port ${slot.port} is occupied before native setup`);
  const project = PROJECTS.find((item) => item.name === slot.project);
  // The host proof runs before the predebit so an unsafe host costs no reservation.
  const { awake, host_awake: hostAwake } = await d.probeHost();
  try {
    return await runHeldLoadRecoverySlotR5({ d, root, freeze, slot, evidence, evidenceFile, project, awake, hostAwake, diagnostic });
  } finally { awake.release(); }
}

async function runHeldLoadRecoverySlotR5({ d, root, freeze, slot, evidence, evidenceFile, project, awake, hostAwake, diagnostic }) {
  const reserve = slot.max_duration_ms;
  const rawDir = `${evidenceFile}.raw`;
  const rawAttempt = createAttemptDirectory(rawDir, slot.id, 1);
  const tempRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'sigra-253-load-r4-'));
  const mono = () => d.monotonicNs();
  const wallNow = () => d.wallMs();
  const ceilMs = (ns) => Math.ceil(Number(ns) / 1e6);
  const started = mono();
  const wallStarted = wallNow();
  // Each phase's remaining time is judged on both clocks, so a sleep that stops the monotonic clock still shortens the window.
  const remainingIn = (ns0, wall0, budgetMs) => Math.min(budgetMs - Number(mono() - ns0) / 1e6, budgetMs - (wallNow() - wall0));
  const database = `sigra_253_control_load_${slot.id.toLowerCase().replaceAll('-', '_')}_${Date.now().toString(36)}_${process.pid}`.toLowerCase();
  const env = diagnosticEnvironment(project, database, tempRoot);
  const tempPaths = Object.fromEntries(['setup_log', 'app_log', 'test_log', 'drop_log'].map((name) => [name, path.join(tempRoot, `${name.replaceAll('_', '-')}.log`)]));
  const reportTemp = path.join(tempRoot, 'playwright-report.json');
  const jsonlTemp = path.join(tempRoot, 'tests.jsonl');
  const outputTemp = path.join(tempRoot, 'playwright-output');
  const attempt = {
    slot_id: slot.id, sequence: slot.sequence, stage: slot.stage, project: slot.project, projects: slot.projects, argv: slot.argv,
    source_commit: freeze.source.checkout_head, source_blobs: freeze.source.blobs, started_monotonic_ns: started.toString(),
    database: { name: database, setup_exit_code: null, drop_exit_code: null, connection: databaseConnectionIdentity(env) },
    server: { port: slot.port, http_status: null, app_pid: null }, browser: { launched: false, exit_code: null },
    playwright_cli: { launched: false, exit_code: null }, lifecycle: { playwright_cli_processes: 0, rows: 0, worker_indexes: [] },
    observed_outcome: 'setup_failed', files: {}, traces: [], registration: { server_post_confirmed: false },
    toolchain: { playwright: null, ecto_sql: freeze.tools.ecto_sql, phoenix_live_view: freeze.tools.phoenix_live_view },
    build_path: env.MIX_BUILD_PATH,
    stage_deadlines: { setup_ms: slot.setup_ms, command_ms: slot.command_ms, work_ms: slot.work_ms, cleanup_ms: slot.cleanup_ms, cleanup_reserved: true },
    host: { platform: awake.platform, sleep_assertion_held: awake.held, sleep_assertion_argv: awake.argv ?? null, suspension_detected: false, holder_alive_at_end: null },
    host_awake: hostAwake, assertion_failure_observed: false, diagnostics: null, per_test_rows: [], ...(slot.retry ? { retry_of: slot.retry_of } : {})
  };
  evidence.status = 'running';
  evidence.reservation = { slot_id: slot.id, mapped_from: slot.maps_from, reserved_ms: reserve, predebited_at: new Date().toISOString(), source_commit: freeze.source.checkout_head };
  evidence.limits.used_slots.push(slot.id);
  writeLoadRecoveryEvidence(evidenceFile, root, evidence, d);
  let app = null; let terminalError = null; let setupEnd = null;
  const playwrightDir = path.join(root, LOAD_PLAYWRIGHT_DIR);
  const examplePath = path.join(root, 'test/example');
  // The command window starts exactly where setup ends, so the two phases tile the slot with no uncharged gap.
  const commandStart = () => setupEnd ?? { ns: started, wall: wallStarted };
  const workRemaining = () => remainingIn(commandStart().ns, commandStart().wall, slot.work_ms);
  const commandRemaining = () => remainingIn(commandStart().ns, commandStart().wall, slot.command_ms);
  const workDeadline = () => ceilMs(commandStart().ns) + slot.work_ms;
  // The R5 count is schema-qualified and keeps its redacted psql stderr beside the stdout log; both are copied into raw.
  // A failed count query is a terminal, non-infrastructure stop that names the first psql error line.
  let countFailure = null;
  const psqlSeam = d.psqlRun ? { run: d.psqlRun } : {};
  const preserveLog = (source, name) => { const target = path.join(rawAttempt, name); fs.copyFileSync(source, target, fs.constants.COPYFILE_EXCL); return target; };
  const captureCount = (name, label, log, deadline) => {
    const receipt = d.captureAccount({ database, email: loadControlAccount(slot.project, 'collision'), env, cwd: examplePath, root, log, deadline, ...psqlSeam });
    attempt[name] = receipt;
    const stem = name.replaceAll('_', '-');
    attempt.files[name] = receiptFile(rawDir, label, preserveLog(log, `${stem}.log`));
    if (fs.existsSync(`${log}.stderr.log`)) attempt.files[`${name}_stderr`] = receiptFile(rawDir, `${label} psql stderr`, preserveLog(`${log}.stderr.log`, `${stem}.stderr.log`));
    if (receipt.exit_code !== 0 || receipt.timed_out || receipt.error) {
      const firstLine = receipt.stderr_first_line || receipt.error || '';
      countFailure = { phase: name, exit_code: receipt.exit_code, timed_out: receipt.timed_out === true, stderr_first_line: firstLine };
      throw new Error(`${label} account count query failed (exit ${receipt.exit_code ?? 'null'}): ${firstLine}`);
    }
    return receipt;
  };
  try {
    // Phase 1: fresh database setup, bounded and charged on its own, before any browser deadline starts.
    let setup = null;
    try { setup = await d.runTree('mix', ['ecto.setup'], examplePath, env, tempPaths.setup_log, remainingIn(started, wallStarted, slot.setup_ms)); }
    finally {
      setupEnd = { ns: mono(), wall: wallNow() };
      attempt.setup_timing = { started_monotonic_ns: started.toString(), ended_monotonic_ns: setupEnd.ns.toString(), execution_ms: ceilMs(setupEnd.ns - started), wall_ms: Math.ceil(setupEnd.wall - wallStarted) };
      attempt.setup_charge_ms = Math.max(attempt.setup_timing.execution_ms, attempt.setup_timing.wall_ms);
    }
    attempt.setup = setup; attempt.database.setup_exit_code = setup.exit_code;
    if (setup.exit_code !== 0 || setup.timed_out) throw new Error(`fresh database setup failed${setup.timed_out ? ' at its setup deadline' : ` with exit ${setup.exit_code ?? 'null'}`}`);
    if (attempt.setup_charge_ms > slot.setup_ms) throw new Error(`fresh database setup overran its frozen ${slot.setup_ms} ms ceiling`);
    // Phase 2: app boot, the CLI and owned cleanup, inside command_ms.
    const appFd = fs.openSync(tempPaths.app_log, 'w');
    try { app = d.spawnApp('mix', ['phx.server'], { cwd: examplePath, env, stdio: ['ignore', appFd, appFd], detached: true }); }
    finally { fs.closeSync(appFd); }
    attempt.server.app_pid = app.pid ?? null;
    attempt.server.http_status = app.pid ? await d.waitReady(app, `http://127.0.0.1:${slot.port}/`, workDeadline()) : null;
    if (attempt.server.http_status !== 200) throw new Error('fresh app did not return HTTP 200 before the reserved work deadline');
    const installed = readJson(path.join(playwrightDir, 'node_modules/@playwright/test/package.json')).version;
    if (installed !== freeze.tools.playwright) throw new Error(`installed Playwright ${installed} differs from the frozen ${freeze.tools.playwright}`);
    attempt.toolchain.playwright = installed;
    if (workRemaining() <= 0) throw new Error('the reserved work deadline passed before browser launch');
    // Every R5 slot is a second window: prove the project's collision account absent (count 0) on this fresh database before the CLI.
    if (captureCount('prior_collision_absence', 'prior collision absence', path.join(tempRoot, 'prior-collision-absence.log'), workDeadline()).count !== 0) throw new Error('prior collision account is not absent from the newly created database');
    attempt.browser.launched = true; attempt.playwright_cli.launched = true; attempt.lifecycle.playwright_cli_processes = 1;
    const args = ['test', freeze.selection.spec, ...slot.argv, `--output=${outputTemp}`];
    attempt.browser_command_argv = args;
    const browser = await d.runTree(path.join(playwrightDir, 'node_modules/.bin/playwright'), args, playwrightDir, {
      ...env, CI: 'true', SIGRA_EXAMPLE_URL: `http://127.0.0.1:${slot.port}`, SIGRA_PLAYWRIGHT_JSON: reportTemp, SIGRA_PLAYWRIGHT_FAILURE_JSONL: jsonlTemp,
      SIGRA_REGISTRATION_CONTROL_STAGE: slot.control_stage, SIGRA_CONTROL_RUN_ID: `${slot.id.toLowerCase()}-${crypto.randomUUID()}`,
      SIGRA_CONTROL_ACCOUNT_PREFIX: 'platform-admin+sigra-253-control', PLAYWRIGHT_HTML_OUTPUT_DIR: path.join(tempRoot, 'html-report')
    }, tempPaths.test_log, workRemaining());
    attempt.test_command = browser; attempt.browser.exit_code = browser.exit_code; attempt.playwright_cli.exit_code = browser.exit_code; attempt.lifecycle.cli_pid = browser.pid ?? null;
    if (browser.timed_out) throw new Error('native Playwright command reached the reserved work deadline');
    if (!fs.existsSync(reportTemp) || fs.statSync(reportTemp).size === 0) throw new Error('native Playwright JSON report is absent or empty');
    const report = readJson(reportTemp);
    const tests = playReportTests(report);
    attempt.assertion_failure_observed = loadR2AssertionFailure(slot, tests);
    for (const item of tests) for (const attachment of item.attachments ?? []) {
      if (attachment.name !== 'trace' && !String(attachment.path ?? '').endsWith('trace.zip')) continue;
      if (!attachment.path || !fs.existsSync(attachment.path)) throw new Error(`native trace attachment for ${item.title} is missing`);
      const target = path.join(rawAttempt, `trace-${attempt.traces.length + 1}.zip`);
      const trace = d.sanitizeTrace(attachment.path, target);
      attempt.traces.push({ ...receiptFile(rawDir, 'sanitized native trace', target), title: item.title, project: item.project, sanitization: trace });
      attachment.path = path.relative(root, target);
    }
    attempt.files.traces = attempt.traces;
    const safeReport = path.join(rawAttempt, 'playwright-report.json');
    fs.writeFileSync(safeReport, `${JSON.stringify(sanitizeReportText(report), null, 2)}\n`, { flag: 'wx' });
    attempt.files.playwright_report = receiptFile(rawDir, 'sanitized native Playwright report', safeReport);
    attempt.lifecycle.rows = tests.length;
    attempt.lifecycle.worker_indexes = [...new Set(tests.flatMap((item) => (Number.isInteger(item.worker_index) ? [item.worker_index] : [])))].sort((a, b) => a - b);
    attempt.lifecycle.context_ids = tests.flatMap((item) => controlContextIdentitiesR4(item));
    attempt.lifecycle.projects_run = [...new Set(tests.map((item) => item.project))];
    attempt.registration.server_post_confirmed = /POST \/users\/log_in/.test(fs.existsSync(tempPaths.app_log) ? fs.readFileSync(tempPaths.app_log, 'utf8') : '');
    captureCount('created_account', 'created account', path.join(tempRoot, 'created-account.log'), workDeadline() + 5000);
    attempt.observed_outcome = 'native_report_pending_validation';
  } catch (error) { terminalError = error.message; }
  finally {
    await d.stopApp(app);
    if (fs.existsSync(tempPaths.app_log)) attempt.log_redactions_app = sanitizeCommandLog(tempPaths.app_log);
    const cleanupRemaining = commandRemaining();
    if (cleanupRemaining <= 0) terminalError = [terminalError, `owned cleanup exceeded the ${slot.command_ms} ms command limit`].filter(Boolean).join('; ');
    const drop = await d.runTree('mix', ['ecto.drop', '--quiet'], examplePath, env, tempPaths.drop_log, Math.max(LOAD_DROP_FLOOR_MS, Math.min(7000, cleanupRemaining - 5000)));
    attempt.database.drop_exit_code = drop.exit_code; attempt.drop_command = drop;
    if (drop.exit_code !== 0 || drop.timed_out) terminalError = [terminalError, `database drop failed${drop.timed_out ? ' at cleanup deadline' : ` with exit ${drop.exit_code ?? 'null'}`}`].filter(Boolean).join('; ');
    if (drop.exit_code === 0 && !drop.timed_out) {
      try {
        const captured = d.captureAbsence({ database, env, cwd: examplePath, log: path.join(tempRoot, 'database-absence.log'), deadline: Math.max(ceilMs(commandStart().ns) + slot.command_ms, ceilMs(mono()) + LOAD_ABSENCE_FLOOR_MS), ...psqlSeam });
        attempt.database.absence_receipt = captured?.stderr_sidecar ? captured.receipt : captured;
        if (captured?.stderr_sidecar) attempt.database.absence_stderr_sidecar = captured.stderr_sidecar;
      }
      catch (error) { terminalError = [terminalError, `independent database absence query failed: ${error.message}`].filter(Boolean).join('; '); }
    }
    try { fs.rmSync(env.MIX_BUILD_PATH, { recursive: true, force: true }); attempt.build_directory_removed = !fs.existsSync(env.MIX_BUILD_PATH); }
    catch (error) { attempt.build_directory_removed = false; terminalError = [terminalError, `physical Mix build cleanup failed: ${error.message}`].filter(Boolean).join('; '); }
  }
  for (const name of ['setup_log', 'app_log', 'test_log', 'drop_log']) {
    if (!fs.existsSync(tempPaths[name])) fs.writeFileSync(tempPaths[name], `${name} command did not start${terminalError ? `: ${terminalError}` : ''}\n`);
    const target = path.join(rawAttempt, `${name.replaceAll('_', '-')}.log`);
    fs.copyFileSync(tempPaths[name], target, fs.constants.COPYFILE_EXCL);
    attempt.files[name] = receiptFile(rawDir, `sanitized ${name}`, target);
  }
  const absenceTemp = path.join(tempRoot, 'database-absence.log');
  if (fs.existsSync(absenceTemp)) {
    const target = path.join(rawAttempt, 'database-absence.log');
    fs.copyFileSync(absenceTemp, target, fs.constants.COPYFILE_EXCL);
    attempt.files.database_absence = receiptFile(rawDir, 'owned database absence query log', target);
  }
  if (fs.existsSync(`${absenceTemp}.stderr.log`)) {
    const target = path.join(rawAttempt, 'database-absence.stderr.log');
    fs.copyFileSync(`${absenceTemp}.stderr.log`, target, fs.constants.COPYFILE_EXCL);
    attempt.files.database_absence_stderr = receiptFile(rawDir, 'owned database absence query stderr', target);
  }
  // Diagnostics are preserved before the temp tree is removed, on a pass, an assertion failure and a deadline kill alike.
  try {
    attempt.diagnostics = preserveAttemptDiagnostics({ outputDir: outputTemp, jsonlPath: jsonlTemp, rawAttempt, rawDir });
    attempt.per_test_rows = attempt.diagnostics.jsonl ? perTestRowsFromJsonl(fs.readFileSync(path.join(rawDir, attempt.diagnostics.jsonl.path), 'utf8')) : [];
  } catch (error) { terminalError = [terminalError, `per-test diagnostics could not be preserved: ${error.message}`].filter(Boolean).join('; '); }
  const ended = mono();
  const wallEnded = wallNow();
  attempt.ended_monotonic_ns = ended.toString();
  attempt.execution_duration_ms = ceilMs(ended - started);
  attempt.wall_duration_ms = Math.ceil(wallEnded - wallStarted);
  const command = commandStart();
  attempt.command_timing = { started_monotonic_ns: command.ns.toString(), ended_monotonic_ns: ended.toString(), execution_ms: ceilMs(ended - command.ns), wall_ms: Math.ceil(wallEnded - command.wall) };
  attempt.command_charge_ms = Math.max(attempt.command_timing.execution_ms, attempt.command_timing.wall_ms);
  attempt.charged_duration_ms = (attempt.setup_charge_ms ?? 0) + attempt.command_charge_ms;
  attempt.host.suspension_detected = [attempt.setup, attempt.test_command, attempt.drop_command].some((result) => result?.suspended === true)
    || Math.abs(attempt.wall_duration_ms - attempt.execution_duration_ms) > TREE_SUSPEND_GAP_MS;
  if (attempt.host.suspension_detected) terminalError = [terminalError, 'host suspension (system sleep or a stalled runner event loop) was detected during the native window, so its timings cannot be accepted'].filter(Boolean).join('; ');
  attempt.host.holder_alive_at_end = Number.isInteger(hostAwake?.holder_pid) ? Boolean(d.holderAlive(hostAwake.holder_pid)) : null;
  if (attempt.host.holder_alive_at_end === false) terminalError = [terminalError, 'the caffeinate sleep-assertion holder was lost during the native window (holder not running), so sleep was no longer prevented'].filter(Boolean).join('; ');
  if (attempt.command_charge_ms > slot.command_ms) terminalError = [terminalError, `native command exceeded its frozen ${slot.command_ms} ms command window`].filter(Boolean).join('; ');
  if (attempt.charged_duration_ms > reserve) terminalError = [terminalError, `native slot exceeded its frozen ${reserve} ms reservation`].filter(Boolean).join('; ');
  const validation = verifyNativeLoadAttemptR5(attempt, freeze, rawDir);
  if (!validation.ok) terminalError = [terminalError, ...validation.errors].filter(Boolean).join('; ');
  evidence.reservation = null;
  evidence.limits.charged_duration_ms += attempt.charged_duration_ms;
  if (attempt.playwright_cli.launched) evidence.limits.physical_playwright_cli_launches += 1;
  evidence.attempts.push(attempt);
  if (slot.retry) {
    evidence.limits.infra_retry.used = 1;
    evidence.infrastructure_retry = { ...evidence.infrastructure_retry, used: true, diagnostic };
  }
  if (terminalError) {
    // Only a host fault (suspension, lost caffeinate holder, host failure before any test ran) with no observed
    // assertion failure is infrastructure, and only the first one is retry-eligible; everything else is terminal.
    const cause = attempt.host.suspension_detected ? 'host_sleep'
      : attempt.host.holder_alive_at_end === false ? 'holder_lost' : null;
    const retryable = Boolean(cause) && !attempt.assertion_failure_observed && !slot.retry
      && evidence.approval?.retry_granted === 1 && evidence.limits.infra_retry?.used === 0;
    if (cause) evidence.infrastructure_halts.push({ slot_id: slot.id, cause, retryable, charged_ms: attempt.charged_duration_ms, assertion_failure_observed: attempt.assertion_failure_observed });
    evidence.stop_reason = terminalError;
    if (retryable) {
      evidence.status = 'halted_infrastructure'; attempt.observed_outcome = 'halted_infrastructure';
      evidence.infrastructure_retry = { eligible: true, halted_slot: slot.id, cause, used: false, diagnostic: null };
    } else { evidence.status = 'halted'; attempt.observed_outcome = 'halted'; }
    // Every terminal stop record lists what each finished test said, read from the preserved per-test JSONL.
    evidence.stop_record = {
      slot_id: slot.id, observed_outcome: attempt.observed_outcome, stop_reason: terminalError, cli_launched: attempt.playwright_cli.launched === true,
      setup_charge_ms: attempt.setup_charge_ms ?? 0, command_charge_ms: attempt.command_charge_ms, charged_duration_ms: attempt.charged_duration_ms, per_test_rows: attempt.per_test_rows,
      ...(countFailure ? { account_count_failure: countFailure } : {})
    };
  } else {
    attempt.observed_outcome = 'native_rows_accepted';
    evidence.status = loadR5AcceptedAttempts(evidence).length === 3 ? 'complete' : 'second_partial';
  }
  writeLoadRecoveryEvidence(evidenceFile, root, evidence, d);
  fs.rmSync(tempRoot, { recursive: true, force: true });
  if (terminalError) throw new Error(terminalError);
  return { status: evidence.status, slot: slot.id, rows: attempt.lifecycle.rows, charged_duration_ms: attempt.charged_duration_ms, physical_playwright_cli_launches: evidence.limits.physical_playwright_cli_launches };
}

