  const carried = {
    revision_commit: '0596dd97a77acafc7dff68b48cba437f3c7e5183', revision_sha256: 'f'.repeat(64), evidence_path: `${PHASE_REL}/253-LOAD-RECOVERY-NATIVE-EVIDENCE-R4.json`,
