TRANSPORT_PATH = Path(__file__).resolve().with_name("ci-hosted-transport.py")
DRIVER_REL = "scripts/ci/ci-shape-probe.py"
TRANSPORT_REL = "scripts/ci/ci-hosted-transport.py"
