      }
    } finally {
      if (previousSubject === undefined) delete process.env.GSD_PROHIB_SUBJECT;
      else process.env.GSD_PROHIB_SUBJECT = previousSubject;
    }
  }

  assert.deepEqual(mismatches, [], `P18 D-30 PARITY: ${mismatches.join('; ')}`);
});

