    assert.equal(refs(fixture.repo), beforeLocal, "busy coordinator gate must preserve all local refs");
    assert.equal(git(fixture.bare, "for-each-ref", "--format=%(refname)%09%(objectname)%09%(objecttype)"), beforeOrigin,
