      assert.match(`${blocked.stdout ?? ""}${blocked.stderr ?? ""}`, /current_pr_ref_contract_blocked|current_open_pr_set_changed|github_pr_pagination_incomplete/,
        `${scenario} PR inventory needs a named public rejection`);
