        runGit(fixture.repo, 'add', fixture.readiness);
        runGit(fixture.repo, '-c', 'gc.auto=0', '-c', 'maintenance.auto=false', 'commit', '-q', '-m', 'fixture: commit incomplete readiness');
        readinessCommit = runGit(fixture.repo, 'rev-parse', 'HEAD');
