// State markers by group board — maps to data-testid="mg-N-{state}" testids
const GROUP_STATE_MARKERS: Record<GroupBoard, string[]> = {
  'board-mg-1': ['mg-1-populated', 'mg-1-zero', 'mg-1-loading', 'mg-1-error'],
